INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('A Thank-You Email to a Host', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nDear Melissa\n\nHow are things [1] London?  I had a great time staying with you.  Thank you for looking after [2] .  You are [3] great cook and your family were really kind to me.  And my English is much better now [4] it was before.  \n\nMy flight home was fine – there were [5] delays at all.  It’s good to be back, but I miss you all very [6] !\n\n[7] you remember my friend Jenny?  I think she came [8] visit me at your house once [9] twice.  Well, she took some great photos [10] us on our last day at the language school.  I’m sending you one with this email.  I hope you like \n\n[11] .\n\nRosario', 'A1', 660, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_0, '[1] Dear Melissa How are things _____ London?', '["to","on","at","in"]', 3, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_0, '[2] Thank you for looking after _____ .', '["me","you","him","her"]', 0, 'Đại từ \'me\' giữ đúng vai trò ngữ pháp (tân ngữ/sở hữu/phản thân) trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_0, '[3] You are _____ great cook and your family were really kind to me.', '["a","an","the","some"]', 0, 'Dùng từ xác định/mạo từ \'a\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_0, '[4] And my English is much better now _____ it was before.', '["than","as","like","so"]', 0, 'Đáp án \'than\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_0, '[5] My flight home was fine – there were _____ delays at all.', '["the","a","an","no"]', 3, 'Đáp án \'no\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_0, '[6] It’s good to be back, but I miss you all very _____ !', '["more","many","much","most"]', 2, '\'much\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_0, '[7] _____ you remember my friend Jenny?', '["Does","Do","Did","Doing"]', 1, 'Đáp án \'Do\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
