INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_0, '[9] I think she came to visit me at your house once _____ twice.', '["so","and","but","or"]', 3, 'Đáp án \'or\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_0, '[10] Well, she took some great photos _____ us on our last day at the language school.', '["of","in","on","at"]', 0, 'Sử dụng giới từ \'of\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_0, '[11] I hope you like _____ .', '["I","it","you","he"]', 1, 'Đáp án \'it\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('A Letter to Aunt Fabienne', 'Read the following text and choose the correct answer for each gap [1] - [12]:\n\nDear Aunt Fabienne,\n\nMum asked [1] to let you know that I arrived home okay. I enjoyed travelling back [2] the train, and I was surprised that [3] only took me three hours to get home. Thank you very [4] for looking after me [5] I was in France. \n\nI’m going back to school [6] week. My French is a lot better [7] it was before, so I hope my marks will improve!\n\nI [8] like to keep practising French and I’m looking [9] a pen friend. I thought of your friend’s son Elian. We could email each [10] once a week. Let me know [11] you think.\n\nI hope [12] see you soon. \n\nDaniel', 'A1', 720, 'PUBLISHED', NOW(), NOW());
