INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('An Invitation to a Birthday Party', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nHi Marta,\n\nI hope [1] are well.  I was trying [2] call you yesterday but you didn’t answer.  Is your phone broken, [3] have you lost it again? \n\nAnyway, I wanted to ask [4] you can come to my birthday party next Saturday.  My birthday was actually two weeks [5] , but I couldn’t have the party then [6] lots of people were [7] holiday.  \n\nI’ve invited [8] few people from our swimming club, as well as my friends from school.  [9] you think your brother [10] free that day?  Please invite [11] to come too.  The party’s at my house and starts at 8p.m.  \n\nParveen', 'A1', 660, 'PUBLISHED', NOW(), NOW());
