INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Inviting Friends to a Barbecue', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nHi Marcia, \n\nDo you remember I wanted [1] invite you, Sasha and John to my new house?  Well, [2] about next Saturday evening?  We [3] a beautiful garden with lots [4] trees.  We may have a barbeque outside [5] it doesn’t rain.  My mother is [6] really good cook and I [7] going to help her make the food.  \n\nAfterwards, [8] don’t we watch a film?  [9] you bring a DVD with you as I haven’t got many here?  \n\nJohn’s coming [10] bike and Sasha is getting a lift [11] her father.  I hope you’ll be able to come too.  \n\nLet me know soon!\n\nConny', 'A1', 660, 'PUBLISHED', NOW(), NOW());
