INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Asking for a Summer Job', 'Read the following text and choose the correct answer for each gap [1] - [12]:\n\nHow [1] you?  I’m writing to you [2] I need your help.\n\nI’m starting a business course at college [3] term.  The teacher has asked us to do some office work during [4] summer.  Your Dad’s [5] manager, isn’t he?  Can you ask him [6] I can work with him?  I only need to work [7] a few weeks, and he will [8] have to pay me anything.\n\nAlso, can I stay [9] you while I’m working?  Mum says it’s much [10] far to go by bike [11] day.  Tell your mum that I can make [12] own meals, so she won’t have to cook for me.\n\nThanks.', 'A1', 720, 'PUBLISHED', NOW(), NOW());
