INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Introducing My Study Abroad Blog', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nWelcome [1] my blog! My name’s Lauren and I’m 22 years old. I come from\n\nIllinois in the USA, but [2] the moment I’m studying in Florence, in Italy.\n\nI’m living [3] a friend of mine from university. Our apartment [4] in the centre of town, so we don’t [5] to use the buses – we can walk everywhere.  I have classes most days, but in [6] afternoon, I explore the city or [7] swimming. When [8] is sunny I visit the Boboli Gardens. [9] are beautiful views of Florence from here.\n\nI [10] you enjoy my blog. [11]  you have any questions, please leave me a message.', 'A1', 660, 'PUBLISHED', NOW(), NOW());
