INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('School Jazz Band', 'Read the following text and choose the correct answer for each gap [1] - [6]:\n\nDo you play a jazz instrument – maybe the trumpet, guitar or drums? Do you want to have some musical fun with other students in the school [1] have similar interests to yours? If you do, come and join us on Tuesdays after school in the music room. At the moment, there are eight of us playing quite a wide range of instruments. We’re having such [2] great time and Mr Jones is an amazing jazz teacher, but we need more people, especially electric guitarists!\n\nWe’re hoping [3] perform in the end-of-term show and Mr Jones said he’ll deal [4] all the technical arrangements and the sound system, which is great! \n\nEither come and ask me [5] more details during one of the lunch breaks, [6] just turn up on the day. But don’t forget to bring your instrument! See you there!\n\nSam (from the School Jazz Band)', 'A2', 360, 'PUBLISHED', NOW(), NOW());
