INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Match report: National Schools Tournament', 'Read the following text and choose the correct answer for each gap [1] - [8]:\n\nBy William Jacobs, football captain\n\nLast Saturday, our school football team took part in the National Schools Tournament. It was a long day – we got to school very early as the bus [1] would take us to the tournament had to leave by 7 a.m. [2] an hour’s drive we arrived at the City Stadium, where the competition was taking [3] . Playing in such [4] famous stadium was an experience we will never forget. \n\nWe played against some [5] the top teams from around the country, and we came first! This was amazing, because the other teams were much stronger this year [6] they were last year. \n\nWe were given our prize, a beautiful silver cup, and then we went on a tour around the stadium. We all agreed that it [7] been an incredible day, and we hope to [8] able to return next year!', 'A2', 480, 'PUBLISHED', NOW(), NOW());
