INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('The Westway Cinema', 'Read the following text and choose the correct answer for each gap [1] - [6]:\n\nThe new Westway Cinema is finally open! I went last night with my brother, and we both agreed it’s much better than the old one [1] to be. Although the ticket prices are higher, the extra cost is worth paying.\n\nThe new owners [2] now taken out all the old seats and put in brand new ones that are really comfortable. There’s also new air conditioning. This is fantastic because in the past it was sometimes [3] hot that it was difficult to concentrate on the film!\n\nThere are also special offers available. For example, [4] you buy two tickets, you can choose something for free – either a snack or a drink. I’m sure this [5] be popular, as you can’t bring [6] own food into the cinema. \n\nI’d really recommend going to the Westway Cinema – it’s a great night out.', 'A2', 360, 'PUBLISHED', NOW(), NOW());
