INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_36, '[4] For example, _____ you buy two tickets, you can choose something for free – either a snack or a drink.', '["unless","whether","if","providing"]', 2, 'Sử dụng liên từ \'if\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
