INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('', 'Read the following text and choose the correct answer for each gap [1] - [8]:\n\nFrom: Harry \n\nTo: Oliver\n\nSubject: Piano lessons \n\nHi Oliver,\n\nGuess what? I’ve finally started piano lessons, like you! As you know, it’s something I’ve wanted to do ever [1] I was young. Anyway, a couple of months ago I saw someone playing the piano on TV – he was brilliant. And when I found out he’d only started playing quite recently, that encouraged [2] to start lessons. \n\nI’ve got a really good teacher, and I go to her house [3] lessons twice a week. She’s very patient. [4] time I make a mistake, she explains what I did wrong. Also, I couldn’t read music when I started, so it’s been hard to learn to read the notes on the page at the [5] time as deciding which piano keys to use! But [6] I finally play something that other people recognise, it really makes me happy. Maybe [7]  day, I’ll become an even better piano player [8] you!', 'A2', 480, 'PUBLISHED', NOW(), NOW());
