INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_37, '[3] I’ve got a really good teacher, and I go to her house _____ lessons twice a week.', '["on","in","for","at"]', 2, 'Sử dụng giới từ \'for\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_37, '[4] _____ time I make a mistake, she explains what I did wrong.', '["All","Every","Both","Either"]', 1, 'Dùng từ xác định/mạo từ \'Every\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
