INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Starting at college', 'Read the following text and choose the correct answer for each gap [1] - [6]:\n\nHi, my name’s Emma. Welcome to the college! I’ve been studying here for a year now. Starting at college isn’t easy, but I’m sure you’ll soon feel at home. When I first started studying here last year, I was [1] nervous that I couldn’t even ask anyone for help. I got lost five times on my first day!\n\nRemember that [2] student at the college has been new at one time, and understands how you feel. So [3] you’re not sure where to go, just ask – we’re all happy to help!\n\nYou probably don’t know many people here. To make some friends, [4] not spend break times with some of your new classmates in the café? Or how [5] joining one of the many clubs we have at the college? [6] are lots to choose from.\n\nGood luck on your new course!', 'A2', 360, 'PUBLISHED', NOW(), NOW());
