INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Letter to a restaurant', 'Read the following text and choose the correct answer for each gap [1] - [8]:\n\nDear Mrs Cutter,\n\nI am writing to complain about a recent visit I made to your restaurant. I went there last Tuesday with my parents, [1] were celebrating their wedding anniversary. We have [2] to your restaurant many times before and always enjoyed it. [3] time, however, there was a problem with the service. \n\nYour restaurant was not very busy on Tuesday evening. In spite [4] that, it took a long time for anyone to come and take our order. We then had to wait for at [5] an hour before the food arrived. As we [6] already arranged to meet some family friends after our meal, we were late meeting them in [7] end because of the slow service at your restaurant.\n\nI suggest that you discuss the issue [8] your staff to prevent it happening again.\n\nYours sincerely,\n\nPeter Hamilton', 'A2', 480, 'PUBLISHED', NOW(), NOW());
