INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Becoming more active', 'Read the following text and choose the correct answer for each gap [1] - [8]:\n\nLast year, I decided that I wasn’t active enough. I was spending too long sitting in [1] of a screen every day and I wasn’t getting as [2] exercise as I needed. So I decided that I would feel a lot better [3] I actually started doing some kind [4] sport. But to be honest, I’m not really into team games. [5] I needed was an outdoor hobby that I could do on my own. Then a friend said I should have a go at mountain-biking, and [6] first time I tried it, I absolutely loved it. There’s a beautiful forest about 5 kilometres [7] my home which is really popular with mountain-bikers. These days, I usually go there twice [8] week. Mountain-biking is a great way to stay fit, and it’s great fun, too!', 'A2', 480, 'PUBLISHED', NOW(), NOW());
