INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Spanish conversation club', 'Read the following text and choose the correct answer for each gap [1] - [6]:\n\nWe’re a group of people aged 16-25 who meet every week for two hours of chat in Spanish. You don’t have to be able to speak much Spanish: we welcome beginners, too. We talk about anything [1] may interest people, from food people enjoy [2] literature and politics. \n\nWe meet between 4.30 [3] 6.30 p.m. every Tuesday, in a large, comfortable room in the Central Library. The sessions are free, but we do ask people to pay £1 a session for coffee or juice. Staff from the School of Tourism at the University set [4] the group three years ago, but it’s now organised [5] volunteers. The number of members [6] grown a lot during this time. As well as allowing people to practise their Spanish, the club brings people from different backgrounds together in order to enjoy each other’s company.', 'A2', 360, 'PUBLISHED', NOW(), NOW());
