INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('A rainy day', 'Read the following text and choose the correct answer for each gap [1] - [6]:\n\nOne summer’s day, my family decided to visit a waterfall in the countryside near our town. As we walked across the fields towards the waterfall, we [1] see it in the distance. It was quite [2] long way, but we got there after about an hour. We sat down near the pool at the bottom of the waterfall to enjoy the picnic that we [3] taken with us. Then we noticed some black clouds in the sky, and some large drops [4] rain fell on us, so we quickly started to collect our things together. Soon the rain began [5] fall heavily. Carrying our bags, we ran as fast as we could, and when we reached the town, we went into the first café we saw. In [6] of our wet clothes, we soon felt better after a delicious drink of hot chocolate!', 'A2', 360, 'PUBLISHED', NOW(), NOW());
