INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('How to hold a fun party', 'Read the following text and choose the correct answer for each gap [1] - [8]:\n\nAre you thinking about holding a party? Then you need [1] make sure it’s lots of fun! Invite plenty [2] people and include a few surprises. For example, if you’re serving food, try ordering ten pizzas [3] are the same flavour but come from different restaurants in your area. Then have a ‘taste test’ and vote on [4] best one. Or [5] about playing games? You could have a video games tournament and offer prizes for the winners. You could also have a singing competition and ask [6] guest to sing a song.\n\nIf your party includes a meal around a table, for each new course, ask your guests to sit next to someone different, in [7] to talk to as many different people [8] possible. Finally, play fun music: your guests might even get up and dance!', 'A2', 480, 'PUBLISHED', NOW(), NOW());
