INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Visit to a sweets factory', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nToday I am visiting a sweets factory, a building squeezed [1] a railway line and a canal.  [2] I watch, trucks filled with sugar arrive at the factory where this family-owned company has been making sweets for some 80 years.\n\nBeing in a factory [3] this one is exactly [4] children dream of.  I am staring at huge vats of sticky liquid [5] eventually ends up as mouth-watering sweets.  Every now [6] then I see a factory worker in a white coat put a sweet into her mouth.\n\nAilsa Kelly, granddaughter of the company owner, remembers visiting the factory as [7] child with her grandfather.  ‘He would take me onto the factory floor and introduce me,’ she says. ‘He told me, “You may work here some day.”’  And indeed, she has, continuously, [8] 1999.  The sense of family is [9] of the reasons employees are remarkably loyal to the company.', 'B1', 540, 'PUBLISHED', NOW(), NOW());
