INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Music therapy', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nIstanbul Memorial Hospital’s Dr Erol Can is reviving music therapy [1] a form of medical treatment.  Dr Can discovered the advantages of music therapy when he worked in a hospital in [2] native country, Bulgaria.  Back in [3] days, he used recorded music.  Gradually, he replaced recordings [4] live music.  He learned to play the flute in [5] to produce the traditional music appropriate for therapy.\n\nThe therapy makes use of the unique psychological and physiological effects of a makam, a form of classical Arab and Turkish music.  [6]  exists a different makam for every health problem.  [7] some makams relax you, others encourage you to be energetic.\n\nDr Can is [8] doing anything new.  The positive effects of music have been known [9] well over 900 years.  In ancient Turkey, hospitals made frequent use of music.', 'B1', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_48, '[1] Istanbul Memorial Hospital’s Dr Erol Can is reviving music therapy _____ a form of medical treatment.', '["for","because","since","as"]', 3, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_48, '[2] Dr Can discovered the advantages of music therapy when he worked in a hospital in _____ native country, Bulgaria.', '["my","his","your","her"]', 1, 'Đại từ \'his\' giữ đúng vai trò ngữ pháp (tân ngữ/sở hữu/phản thân) trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_48, '[3] Back in _____ days, he used recorded music.', '["those","this","that","these"]', 0, 'Đáp án \'those\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_48, '[4] Gradually, he replaced recordings _____ live music.', '["with","in","on","at"]', 0, 'Sử dụng giới từ \'with\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
