INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_48, '[6] _____ exists a different makam for every health problem.', '["they","it","here","there"]', 3, 'Đáp án \'there\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
