INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_48, '[8] Dr Can is _____ doing anything new.', '["none","no","never","not"]', 3, 'Đáp án \'not\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
