INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Animal communication', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nIt [1] sometimes said that animals use language.  Certainly some animal species have developed amazingly sophisticated ways of communicating with [2] another. \n\nBut there are huge differences between the ways animals communicate and the ways human beings do.  When animals make a sound, such [3] a bark or a call, it is in reaction to [4] is happening around them. An alarm call means they are frightened.  A hunger call means they want food.  Animals, though, cannot make a call meaning ‘I was scared yesterday’ or ‘I’ll be hungry tomorrow’.  Only human beings are capable [5] doing this.\n\nZoologists have had some success in teaching human language to animals. [6] some famous experiments, chimpanzees have [7] taught to use their hands to give information on a range of things. Some animals have even managed to put signs together in [8] to make simple sentences. However, getting them to do this takes a huge [9] of training.', 'B1', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_49, '[1] It _____ sometimes said that animals use language.', '["was","am","are","is"]', 3, 'Đáp án \'is\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_49, '[2] Certainly some animal species have developed amazingly sophisticated ways of communicating with _____ another.', '["a","one","an","the"]', 1, 'Đáp án \'one\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_49, '[3] When animals make a sound, such _____ a bark or a call, it is in reaction to what is happening around them.', '["because","as","since","for"]', 1, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
