INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_50, '[3] One such school is run by Kathleen Doyle not _____ from the centre of Dublin.', '["away","near","far","distant"]', 2, 'Đáp án \'far\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
