INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_50, '[7] ’ Just _____ most cookery schools in Ireland, Kathleen initially copied the classical dishes of France and Italy and other countries which have a reputation for excellent food.', '["so","than","as","like"]', 3, 'Đáp án \'like\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
