INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Biomimicry – learning from nature', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nBiomimicry is a term popularized [1] science writer Janine Benyus in her 1997 book of [2] same name.  It refers to the expanding field in [3] scientists and designers look to nature for solutions to many sorts of problems.  Biomimicry is based [4] studying what can usefully [5] learnt from nature.  However, the most significant biomimicry breakthroughs have come not from actually copying nature, [6] from studying the principles behind natural systems and then applying [7] to human needs.  \n\nDirect copying may lead [8] poor engineering designs.  For example, in the past, [9] humans constructed devices with flapping wings, they generally failed to fly.  Ultimately, the Wright brothers created the first successful plane by understanding the subtleties of bird flight and adapting its principles to their fixed-wing plane.  Today, increased scientific understanding of the natural world should result [10] promising commercial applications for  [11] areas as aerospace, smart sensors and robotics.', 'B1', 660, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_51, '[1] Biomimicry is a term popularized _____ science writer Janine Benyus in her 1997 book of the same name.', '["at","in","on","by"]', 3, 'Sử dụng giới từ \'by\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_51, '[2] Biomimicry is a term popularized by science writer Janine Benyus in her 1997 book of _____ same name.', '["a","the","an","some"]', 1, 'Dùng từ xác định/mạo từ \'the\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_51, '[3] It refers to the expanding field in _____ scientists and designers look to nature for solutions to many sorts of problems.', '["which","who","whom","whose"]', 0, 'Đại từ quan hệ \'which\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_51, '[4] Biomimicry is based _____ studying what can usefully be learnt from nature.', '["at","in","on","to"]', 2, 'Sử dụng giới từ \'on\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_51, '[5] Biomimicry is based on studying what can usefully _____ learnt from nature.', '["are","am","is","be"]', 3, 'Đáp án \'be\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_51, '[6] However, the most significant biomimicry breakthroughs have come not from actually copying nature, _____ from studying the principles behind natural systems and then applying them to human needs.', '["although","but","though","even though"]', 1, 'Đáp án \'but\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
