INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Bamboo musical instruments', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nAs anyone who [1] travelled in Asia knows, bamboo is a common tree-sized plant, used to make furniture as [2] as various household items.  Bamboo is also used extensively in the creation [3] musical instruments.  In China, [4] country where the largest number of bamboo varieties grow naturally, the bamboo dizi flute is found.  This has one hole, covered by a paper-thin sheet also made from bamboo, [5] vibrates, creating the instrument’s distinctive sound.  In Japan, the shakuhachi flute is named [6] the length of bamboo required to make [7] .  The Indian bansuri bamboo flute, when played by a master musician [8] as the great Hariprasad Chaurasia, is a major classical instrument.  [9] most bamboo musical instruments are Asian, they are also found [10] the traditional music of Africa and the Americas,  For example, the national instrument of Madagascar, the valiha, is made from bamboo, as [11] the quena flutes of the Andes.', 'B1', 660, 'PUBLISHED', NOW(), NOW());
