INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_52, '[3] Bamboo is also used extensively in the creation _____ musical instruments.', '["in","of","on","at"]', 1, 'Sử dụng giới từ \'of\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_52, '[4] In China, _____ country where the largest number of bamboo varieties grow naturally, the bamboo dizi flute is found.', '["some","a","an","the"]', 3, 'Dùng từ xác định/mạo từ \'the\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
