INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_52, '[7] In Japan, the shakuhachi flute is named after the length of bamboo required to make _____ .', '["I","it","you","he"]', 1, 'Đáp án \'it\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_52, '[8] The Indian bansuri bamboo flute, when played by a master musician _____ as the great Hariprasad Chaurasia, is a major classical instrument.', '["such","very","too","so"]', 0, 'Đáp án \'such\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_52, '[9] _____ most bamboo musical instruments are Asian, they are also found in the traditional music of Africa and the Americas, For example, the national instrument of Madagascar, the valiha, is made from bamboo, as are the quena flutes of the Andes.', '["Even though","Although","Whereas","However"]', 1, 'Sử dụng liên từ \'Although\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_52, '[10] Although most bamboo musical instruments are Asian, they are also found _____ the traditional music of Africa and the Americas, For example, the national instrument of Madagascar, the valiha, is made from bamboo, as are the quena flutes of the Andes.', '["in","on","at","to"]', 0, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_52, '[11] Although most bamboo musical instruments are Asian, they are also found in the traditional music of Africa and the Americas, For example, the national instrument of Madagascar, the valiha, is made from bamboo, as _____ the quena flutes of the Andes.', '["is","am","are","was"]', 2, 'Đáp án \'are\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Heavy birds that travel long distances', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nThe bustard is [1] of the world’s heaviest birds.  Male bustards weigh between 10 and 15 kilogrammes, while the female is considerably lighter at about five kilogrammes.  [2] their great weight, bustards are still able to fly great distances.\n\nIn order to find out just [3] far bustards can fly, a group of American researchers fitted several bustards in northern Mongolia with tracking devices.  They discovered that [4] year the bustards fly to China’s Shaanxi province to get well away from the harsh Mongolian winter, and then, a [5] months later, return to Mongolia.  The length of the journey to and from China is 4,000 kilometres.\n\nIt seems surprising that such heavy birds are [6] of flying so far.  Apparently, they manage to do so [7] making frequent and lengthy stops.  [8] their journey takes four months, the birds spend only two to six per cent of the time actually in the air. The remainder of the time [9] spent resting.', 'B1', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_53, '[1] The bustard is _____ of the world’s heaviest birds.', '["one","a","an","the"]', 0, 'Đáp án \'one\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_53, '[2] _____ their great weight, bustards are still able to fly great distances.', '["Although","Despite","Though","Even though"]', 1, 'Sử dụng liên từ \'Despite\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_53, '[3] In order to find out just _____ far bustards can fly, a group of American researchers fitted several bustards in northern Mongolia with tracking devices.', '["which","what","how","where"]', 2, 'Đáp án \'how\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_53, '[4] They discovered that _____ year the bustards fly to China’s Shaanxi province to get well away from the harsh Mongolian winter, and then, a few months later, return to Mongolia.', '["all","every","both","either"]', 1, 'Dùng từ xác định/mạo từ \'every\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_53, '[5] They discovered that every year the bustards fly to China’s Shaanxi province to get well away from the harsh Mongolian winter, and then, a _____ months later, return to Mongolia.', '["few","much","many","more"]', 0, '\'few\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_53, '[6] It seems surprising that such heavy birds are _____ of flying so far.', '["able","capable","competent","fitted"]', 1, 'Đáp án \'capable\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_53, '[7] Apparently, they manage to do so _____ making frequent and lengthy stops.', '["in","by","on","at"]', 1, 'Sử dụng giới từ \'by\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_53, '[8] _____ their journey takes four months, the birds spend only two to six per cent of the time actually in the air.', '["Although","Even though","Whereas","However"]', 0, 'Sử dụng liên từ \'Although\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_53, '[9] The remainder of the time _____ spent resting.', '["was","am","are","is"]', 3, 'Đáp án \'is\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Golf', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nThe game of golf is played [1] countries all over the world.  However, nobody is sure [2] the precise date when golf started.  It seems that ball and stick games have [3] played throughout human history.  Records show that in the fourteenth century the Dutch played a game called koft in [4] players had to hit a ball against a stick in the ground.  In the fifteenth century, Scottish merchants [5] had been doing business in Holland saw the game and took the idea back with [6] to Scotland.  The Scots made a significant change to the game, though. [7] than using a stick as their target, they started to use a hole.\n\nOriginally, holes could be of [8] size.  However, since 1891 holes have had to be exactly 4.25 inches (10.8 centimetres) wide.  This is because the official rule book was written by the Royal and Ancient Golf Club of St Andrews and the tool they had always used [9] cutting holes was 4.25 inches wide.', 'B1', 540, 'PUBLISHED', NOW(), NOW());
