INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_54, '[2] However, nobody is sure _____ the precise date when golf started.', '["of","in","on","at"]', 0, 'Sử dụng giới từ \'of\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_54, '[3] It seems that ball and stick games have _____ played throughout human history.', '["are","am","is","been"]', 3, 'Đáp án \'been\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_54, '[4] Records show that in the fourteenth century the Dutch played a game called koft in _____ players had to hit a ball against a stick in the ground.', '["who","which","whom","whose"]', 1, 'Đại từ quan hệ \'which\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_54, '[5] In the fifteenth century, Scottish merchants _____ had been doing business in Holland saw the game and took the idea back with them to Scotland.', '["who","whom","whose","which"]', 0, 'Đại từ quan hệ \'who\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
