INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_54, '[7] _____ than using a stick as their target, they started to use a hole.', '["Very","Rather","Too","So"]', 1, 'Đáp án \'Rather\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_54, '[8] Originally, holes could be of _____ size.', '["the","a","an","any"]', 3, 'Dùng từ xác định/mạo từ \'any\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_54, '[9] This is because the official rule book was written by the Royal and Ancient Golf Club of St Andrews and the tool they had always used _____ cutting holes was 4.25 inches wide.', '["for","in","on","at"]', 0, 'Sử dụng giới từ \'for\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('An ancient plant', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nRussian scientists have succeeded [1] growing an ancient plant using a remarkable method of reconstruction. [2] many years, fruit from the plant lay undisturbed in the frozen soil of Siberia, called permafrost. The fruit [3] been stored by rodents in the ground some 30,000 years before the scientists unearthed it. Dirt gradually covered the rodents’ store, eventually leaving it 38 meters beneath the frozen ground, [4] kept the contents well preserved.\n\nThe scientists used the fruit tissue to create a plant and in [5] way produced a specimen bearing flowers and fertile seeds. At first, the scientists thought the reconstituted plant to [6] a member of an existing species. But as [7] as its white flowers appeared, the scientists saw that the petals were narrower and less clearly separated [8] those of today’s species. Biologists say [9] is remarkable that the Russian scientists could use fruit tissues for reproduction after such [10] long time.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
