INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_55, '[2] _____ many years, fruit from the plant lay undisturbed in the frozen soil of Siberia, called permafrost.', '["In","For","On","At"]', 1, 'Sử dụng giới từ \'For\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_55, '[3] The fruit _____ been stored by rodents in the ground some 30,000 years before the scientists unearthed it.', '["has","have","had","having"]', 2, 'Đáp án \'had\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
