INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_55, '[5] The scientists used the fruit tissue to create a plant and in _____ way produced a specimen bearing flowers and fertile seeds.', '["these","this","those","in"]', 1, 'Đáp án \'this\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_55, '[6] At first, the scientists thought the reconstituted plant to _____ a member of an existing species.', '["be","am","is","are"]', 0, 'Đáp án \'be\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_55, '[7] But as _____ as its white flowers appeared, the scientists saw that the petals were narrower and less clearly separated than those of today’s species.', '["quickly","early","fast","soon"]', 3, 'Đáp án \'soon\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_55, '[8] But as soon as its white flowers appeared, the scientists saw that the petals were narrower and less clearly separated _____ those of today’s species.', '["than","as","like","so"]', 0, 'Đáp án \'than\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_55, '[9] Biologists say _____ is remarkable that the Russian scientists could use fruit tissues for reproduction after such a long time.', '["he","I","you","it"]', 3, 'Đáp án \'it\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_55, '[10] Biologists say it is remarkable that the Russian scientists could use fruit tissues for reproduction after such _____ long time.', '["some","an","the","a"]', 3, 'Dùng từ xác định/mạo từ \'a\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('A family interest in science', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nMy mother was particularly attracted to chemistry [1] she was a girl, although she later became a biologist. However, she [2] lost her love of chemistry, nor the desire to go beneath the surface of things. This meant that the thousands of questions I asked [3] a child were met not by impatient answers, [4] rather by careful, thoughtful ones.\n\nI sometimes begged my mother to take off her ring [5] I could inspect the diamond in it. It flashed like nothing else I [6] ever seen before. It was almost as [7] the diamond gave off a bright light of [8] own. Mother showed me [9] easily the diamond could scratch glass, and then told me to put it to my lips. It was strangely, startlingly cold. That was because it conducted heat so well, she said, so it drew the body heat away [10] your lips when they touched it. I have always remembered the feeling.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_56, '[1] My mother was particularly attracted to chemistry _____ she was a girl, although she later became a biologist.', '["since","when","for","during"]', 1, 'Đại từ quan hệ \'when\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_56, '[2] However, she _____ lost her love of chemistry, nor the desire to go beneath the surface of things.', '["barely","hardly","scarcely","never"]', 3, 'Đáp án \'never\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_56, '[3] This meant that the thousands of questions I asked _____ a child were met not by impatient answers, but rather by careful, thoughtful ones.', '["because","as","since","for"]', 1, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
