INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_56, '[7] It was almost as _____ the diamond gave off a bright light of its own.', '["whether","if","unless","provided"]', 1, 'Sử dụng liên từ \'if\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
