INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Swimming the Channel', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nAt the narrowest point, the distance across the English Channel, the stretch of water separating England [1] France, is 34 kilometres. In August 1875, Matthew Webb became the first person to swim the Channel. He dived into the sea near Dover and, even [2] he was kept off the French coast by strong currents for five hours, he finally reached France 21 hours 45 minutes [3] . Since then, almost 1500 people [4] swum the Channel, some of them setting        [5] from France, others from England.\n\nHowever, [6] was not until fifty years after Webb’s achievement that the first woman, Gertrude Ederle from the US, successfully made the crossing. Despite the slow start made by women, it is a woman who holds the record for swimming the Channel the [7] times. Alison Streeter has done so on no fewer [8] forty occasions – incredibly, in [9] year alone, 1992, she did the crossing seven times!', 'B1', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_57, '[1] At the narrowest point, the distance across the English Channel, the stretch of water separating England _____ France, is 34 kilometres.', '["in","from","on","at"]', 1, 'Sử dụng giới từ \'from\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_57, '[2] He dived into the sea near Dover and, even _____ he was kept off the French coast by strong currents for five hours, he finally reached France 21 hours 45 minutes later .', '["though","although","even though","while"]', 0, 'Sử dụng liên từ \'though\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_57, '[3] He dived into the sea near Dover and, even though he was kept off the French coast by strong currents for five hours, he finally reached France 21 hours 45 minutes _____ .', '["later","sooner","then","in"]', 0, 'Đáp án \'later\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_57, '[4] Since then, almost 1500 people _____ swum the Channel, some of them setting out from France, others from England.', '["have","has","had","having"]', 0, 'Đáp án \'have\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
