INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_57, '[8] Alison Streeter has done so on no fewer _____ forty occasions – incredibly, in one year alone, 1992, she did the crossing seven times!', '["than","as","like","so"]', 0, 'Đáp án \'than\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
