INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Ghost writing', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nMany bookshops seem to be full [1] the autobiographies of celebrities. How, you may wonder, can celebrities find time to write books? In reality, of [2], they rarely write the books themselves – they employ people known [3] ‘ghost writers’.\n\nGhost writers have the skill to organise another person’s ideas and to present them clearly in written form. [4] are, however, variations in the way work is divided up between the ghost writer and the celebrity. Sometimes a ghost writer has simply to edit a piece of work which is [5] or less complete. [6] this happens, the ideas and much of the language in the finished book [7] those of the celebrity. In many cases, though, the ghost writer will be responsible for most, if not [8], of the writing. The writer will then have to do a substantial amount of documentary research as [9] as interviewing the celebrity’s family and friends.', 'B1', 540, 'PUBLISHED', NOW(), NOW());
