INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_58, '[2] In reality, of _____, they rarely write the books themselves – they employ people known as ‘ghost writers’.', '["course","sure","certain","way"]', 0, 'Đáp án \'course\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
