INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Huh?', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nOur speech is full [1] ‘words’ like ah, um and mm. Yet linguistic scholars have not paid much attention to such sounds [2] now. Researchers at the Max Planck Institute in the Netherlands [3] recently reported to have uncovered a surprisingly important role for the sound huh?  This is a kind of voiced question mark people use [4] signal that they don’t understand something. [5] a result of their studies, the researchers believe that huh? is a ‘universal word’, the first to [6] studied by modern linguists.\n\nThe research team analysed recordings of people speaking ten common languages, including Spanish and Chinese, as [7] as native languages from Ecuador, Australia and Ghana. Not [8] did all these have a word used in [9] to prompt a quick clarification, but its form always resembled huh? The utterance, argue the researchers, is a remarkable linguistic invention. Importantly, huh? is brief and easy to produce [10] any complicated movement of the tongue or lips and does not sound threatening.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
