INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_61, '[2] It was particularly strong in an American cat called Ninja, which disappeared shortly _____ its owners had taken it to their new home; a year later the cat turned up at its old home even though this was 1,360 kilometres away from where its owners were now living.', '["during","since","for","after"]', 3, 'Đáp án \'after\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
