INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('The importance of talking to young children', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nParents often read a story to [1] young children before the children go to sleep. This is an activity [2] benefits both the adults and the children. Reading and chatting to children should [3] encouraged because they are not simply enjoyable [4] are also important in helping to develop children’s intelligence. [5] to some psychologists, children are unlikely to achieve their full potential [6] adults rarely read to them.\n\nA research project was set up to investigate [7] or not intellectual development is linked to the number of words children hear. In order to check the number of words children from different backgrounds heard each day, microphones [8] attached to children’s clothing. Apparently, some 18-month-old children hear as [9] as 12,000 words a day while others heard only 600. The research managed to establish that [10] was a significant link [11] successful mental processing and the number of words heard; the more words heard, the better the progress.', 'B1', 660, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_62, '[1] Parents often read a story to _____ young children before the children go to sleep.', '["your","my","their","his"]', 2, 'Đại từ \'their\' giữ đúng vai trò ngữ pháp (tân ngữ/sở hữu/phản thân) trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_62, '[2] This is an activity _____ benefits both the adults and the children.', '["whose","who","whom","which"]', 3, 'Đại từ quan hệ \'which\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_62, '[3] Reading and chatting to children should _____ encouraged because they are not simply enjoyable but are also important in helping to develop children’s intelligence.', '["am","be","is","are"]', 1, 'Đáp án \'be\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_62, '[4] Reading and chatting to children should be encouraged because they are not simply enjoyable _____ are also important in helping to develop children’s intelligence.', '["even though","although","though","but"]', 3, 'Đáp án \'but\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_62, '[5] _____ to some psychologists, children are unlikely to achieve their full potential if adults rarely read to them.', '["owing","due","according","referring"]', 2, 'Đáp án \'according\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_62, '[6] according to some psychologists, children are unlikely to achieve their full potential _____ adults rarely read to them.', '["if","whether","unless","provided"]', 0, 'Sử dụng liên từ \'if\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_62, '[7] A research project was set up to investigate _____ or not intellectual development is linked to the number of words children hear.', '["unless","if","whether","provided"]', 2, 'Sử dụng liên từ \'whether\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_62, '[8] In order to check the number of words children from different backgrounds heard each day, microphones _____ attached to children’s clothing.', '["were","am","is","are"]', 0, 'Đáp án \'were\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_62, '[9] Apparently, some 18-month-old children hear as _____ as 12,000 words a day while others heard only 600.', '["more","many","most","less"]', 1, '\'many\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_62, '[10] The research managed to establish that _____ was a significant link between successful mental processing and the number of words heard; the more words heard, the better the progress.', '["they","it","here","there"]', 3, 'Đáp án \'there\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_62, '[11] The research managed to establish that there was a significant link _____ successful mental processing and the number of words heard; the more words heard, the better the progress.', '["on","in","between","at"]', 2, 'Sử dụng giới từ \'between\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('The importance of reading', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nReading is good [1] us. In fact, there is plenty of evidence that reading for pleasure is [2] merely another leisure pursuit but that it actually improves our mental and physical health. Reading extended texts [3] as novels or biographies, [4] requires intense concentration for a considerable period of time, helps to lengthen attention spans in children and improves their ability to think clearly. However, experts say [5] is essential to acquire the habit of reading extensively [6] a small child, while the brain is still developing.\n\nReading can undoubtedly [7] beneficial to our mental well-being. Reading not [8] helps combat feelings of loneliness, it also allows people to relax and forget their problems for [9] while. The concentration required during the act of reading seems to ease muscle tension and slow the heart rate. Researchers have found that just six minutes of reading can reduce stress levels by as [10] as two-thirds.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_63, '[1] Reading is good _____ us.', '["for","in","on","at"]', 0, 'Sử dụng giới từ \'for\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_63, '[2] In fact, there is plenty of evidence that reading for pleasure is _____ merely another leisure pursuit but that it actually improves our mental and physical health.', '["no","not","never","none"]', 1, 'Đáp án \'not\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_63, '[3] Reading extended texts _____ as novels or biographies, which requires intense concentration for a considerable period of time, helps to lengthen attention spans in children and improves their ability to think clearly.', '["so","very","too","such"]', 3, 'Đáp án \'such\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_63, '[4] Reading extended texts such as novels or biographies, _____ requires intense concentration for a considerable period of time, helps to lengthen attention spans in children and improves their ability to think clearly.', '["who","which","whom","whose"]', 1, 'Đại từ quan hệ \'which\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_63, '[5] However, experts say _____ is essential to acquire the habit of reading extensively as a small child, while the brain is still developing.', '["he","I","you","it"]', 3, 'Đáp án \'it\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_63, '[6] However, experts say it is essential to acquire the habit of reading extensively _____ a small child, while the brain is still developing.', '["as","because","since","for"]', 0, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_63, '[7] Reading can undoubtedly _____ beneficial to our mental well-being.', '["am","be","is","are"]', 1, 'Đáp án \'be\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_63, '[8] Reading not _____ helps combat feelings of loneliness, it also allows people to relax and forget their problems for a while.', '["only","just","merely","alone"]', 0, 'Đáp án \'only\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_63, '[9] Reading not only helps combat feelings of loneliness, it also allows people to relax and forget their problems for _____ while.', '["the","an","a","some"]', 2, 'Dùng từ xác định/mạo từ \'a\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_63, '[10] Researchers have found that just six minutes of reading can reduce stress levels by as _____ as two-thirds.', '["more","many","much","most"]', 2, '\'much\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('The joys of horse riding', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nFor me, riding a horse is a delightful combination [1] adventure, excitement and relaxation. You can proceed at a slow, peaceful trot [2] choose to go at full speed, [3] you should fancy that. [4] I love most about being on a horse is that you get a different view of the world, seeing things you would [5] normally see, totally surrounded by nature. Each ride has [6] own appeal. I especially cherish cold, crisp days in winter [7] the ground sparkles with snow. Even riding in the rain has a certain appeal – splashing through puddles and galloping home as quickly [8] you can to escape the next downpour. [9] paths you ride along may be familiar, you can never quite predict the surprises beyond the next corner. Riding alone can be fabulous, but going out on horses with a friend is best of [10] . Even the horses seem to enjoy the company of each [11] .', 'B1', 660, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_64, '[1] For me, riding a horse is a delightful combination _____ adventure, excitement and relaxation.', '["at","in","on","of"]', 3, 'Sử dụng giới từ \'of\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_64, '[2] You can proceed at a slow, peaceful trot _____ choose to go at full speed, if you should fancy that.', '["or","and","but","so"]', 0, 'Đáp án \'or\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_64, '[3] You can proceed at a slow, peaceful trot or choose to go at full speed, _____ you should fancy that.', '["whether","if","unless","provided"]', 1, 'Sử dụng liên từ \'if\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_64, '[4] _____ I love most about being on a horse is that you get a different view of the world, seeing things you would not normally see, totally surrounded by nature.', '["what","who","whom","whose"]', 0, 'Đáp án \'what\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_64, '[5] what I love most about being on a horse is that you get a different view of the world, seeing things you would _____ normally see, totally surrounded by nature.', '["not","no","none","in"]', 0, 'Đáp án \'not\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_64, '[6] Each ride has _____ own appeal.', '["my","its","your","his"]', 1, 'Đáp án \'its\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_64, '[7] I especially cherish cold, crisp days in winter _____ the ground sparkles with snow.', '["during","since","for","when"]', 3, 'Đại từ quan hệ \'when\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_64, '[8] Even riding in the rain has a certain appeal – splashing through puddles and galloping home as quickly _____ you can to escape the next downpour.', '["since","because","as","for"]', 2, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_64, '[9] _____ paths you ride along may be familiar, you can never quite predict the surprises beyond the next corner.', '["even though","although","whilst","whereas"]', 1, 'Sử dụng liên từ \'although\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_64, '[10] Riding alone can be fabulous, but going out on horses with a friend is best of _____ .', '["both","all","each","every"]', 1, 'Dùng từ xác định/mạo từ \'all\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_64, '[11] Even the horses seem to enjoy the company of each _____ .', '["other","another","others","the other"]', 0, 'Đáp án \'other\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('The importance of laughter', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nPsychologists tell us that humour and laughter are good [1] our social relationships. Having a good sense of humour is often regarded [2] being one of the most important characteristics that people look [3] in a friend. In classrooms, a humorous teacher can make learning far [4] enjoyable and improve a student’s motivation.\n\nIn one study, students on a psychology course [5] split into three different groups: one group was taught with a certain amount of humour, and the other with [6] humour at all. Later when researchers tested the students to see [7] much they had retained of [8] they had heard in the lectures, they found that those [9] had attended lectures with course-related humour scored significantly higher than the other students.\n\nHumour and laughter make us feel happy, and our laughter makes others laugh as [10] , so if we laugh a lot we may be helping to make other people feel happy.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_65, '[1] Psychologists tell us that humour and laughter are good _____ our social relationships.', '["for","in","on","at"]', 0, 'Sử dụng giới từ \'for\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_65, '[2] Having a good sense of humour is often regarded _____ being one of the most important characteristics that people look for in a friend.', '["as","because","since","for"]', 0, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_65, '[3] Having a good sense of humour is often regarded as being one of the most important characteristics that people look _____ in a friend.', '["on","in","for","at"]', 2, 'Sử dụng giới từ \'for\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_65, '[4] In classrooms, a humorous teacher can make learning far _____ enjoyable and improve a student’s motivation.', '["more","much","many","most"]', 0, '\'more\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_65, '[5] In one study, students on a psychology course _____ split into three different groups: one group was taught with a certain amount of humour, and the other with no humour at all.', '["am","were","is","are"]', 1, 'Đáp án \'were\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_65, '[6] In one study, students on a psychology course were split into three different groups: one group was taught with a certain amount of humour, and the other with _____ humour at all.', '["no","a","an","the"]', 0, 'Đáp án \'no\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_65, '[7] Later when researchers tested the students to see _____ much they had retained of what they had heard in the lectures, they found that those who had attended lectures with course-related humour scored significantly higher than the other students.', '["which","what","how","where"]', 2, 'Đáp án \'how\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
