INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_65, '[10] Humour and laughter make us feel happy, and our laughter makes others laugh as _____ , so if we laugh a lot we may be helping to make other people feel happy.', '["better","good","well","best"]', 2, 'Đáp án \'well\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('The origins of coins', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nAccording [1] the Greek historian Herodotus (585-524 BC), the Lydian people, living in what is modern Turkey, were the first to use metallic coins. In fact, these earliest coins were made out [2] electrum, a naturally-occurring mixture of gold and silver. The coins were first produced in the seventh century BC with a design on [3] side only; the other was marked with simple punches. Each coin was assigned a value in units known [4] ‘staters’. Some coins were inscribed with names in Lydian script, but it is unclear [5] these are names of kings or just of rich men who produced the coins. [6] of the irregular size and shape of the coins, it must [7] been difficult to tell them [8] , especially some of the smaller ones. Thus, many costs were expressed [9] terms of the total weight of the coins required and transactions were completed by weighing the coins used together, [10] than counting individual ones.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_66, '[1] According _____ the Greek historian Herodotus (585-524 BC), the Lydian people, living in what is modern Turkey, were the first to use metallic coins.', '["at","in","on","to"]', 3, 'Sử dụng giới từ \'to\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_66, '[2] In fact, these earliest coins were made out _____ electrum, a naturally-occurring mixture of gold and silver.', '["of","in","on","at"]', 0, 'Sử dụng giới từ \'of\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_66, '[3] The coins were first produced in the seventh century BC with a design on _____ side only; the other was marked with simple punches.', '["an","a","one","the"]', 2, 'Đáp án \'one\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_66, '[4] Each coin was assigned a value in units known _____ ‘staters’.', '["since","because","as","for"]', 2, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_66, '[5] Some coins were inscribed with names in Lydian script, but it is unclear _____ these are names of kings or just of rich men who produced the coins.', '["whether","unless","provided","providing"]', 0, 'Sử dụng liên từ \'whether\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_66, '[6] _____ of the irregular size and shape of the coins, it must have been difficult to tell them apart , especially some of the smaller ones.', '["Since","Because","As","For"]', 1, 'Sử dụng liên từ \'Because\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
