INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_66, '[10] Thus, many costs were expressed in terms of the total weight of the coins required and transactions were completed by weighing the coins used together, _____ than counting individual ones.', '["rather","very","too","so"]', 0, 'Đáp án \'rather\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Gardening', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nIt is early summer, the season of abundance, when my garden is [1] its fullest. Flowers are [2] bloom and the grass is growing [3] fast that half an hour after cutting it, I seem to be back [4] I started.\n\nThis year for the first time I am attempting to grow [5] own vegetables, an attempt that has so [6] proved very successful. My vegetable plants have been yielding an abundance of produce, in fact much [7] than I can possibly consume myself.\n\nI’m convinced that you cannot plant even a single tomato [8] feeling a connection to the earth and to the countless generations who have worked the land before you. To plant seeds and then to harvest what you have grown gives [9] deep sense of satisfaction. I believe that many doctors and mental health organisations all [10] the world now recognise the value of gardening to the well-being of those [11] take part in this activity.', 'B1', 660, 'PUBLISHED', NOW(), NOW());
