INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_67, '[3] Flowers are in bloom and the grass is growing _____ fast that half an hour after cutting it, I seem to be back where I started.', '["because","so","since","as"]', 1, 'Sử dụng liên từ \'so\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_67, '[4] Flowers are in bloom and the grass is growing so fast that half an hour after cutting it, I seem to be back _____ I started.', '["who","where","whom","whose"]', 1, 'Đại từ quan hệ \'where\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
