INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_67, '[10] I believe that many doctors and mental health organisations all _____ the world now recognise the value of gardening to the well-being of those who take part in this activity.', '["around","in","on","at"]', 0, 'Đáp án \'around\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
