INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Message in a bottle', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nBottles containing messages [1] occasionally found on sea shores. [2] time ago a couple came across such [3] bottle on an island in the North Sea. The message in the bottle asked for it to be returned to George Parker Bidder at a scientific association in England along [4] information about where it was found. The couple did [5] requested and sent the bottle back.\n\nBidder had once been president of the association and had carried [6] research into ocean currents. It appeared that as part of his research he had thrown a thousand bottles into the sea in [7] to help him map the direction of the currents. The scientists realised that the bottle they had been sent was [8] of those thousand bottles. [9] amazed them, though, was that it was 110 years [10] Bidder had thrown the bottles into the sea.\n\nFortunately for Bidder’s research, most of his bottles had come back within a [11] months.', 'B1', 660, 'PUBLISHED', NOW(), NOW());
