INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_68, '[3] Some time ago a couple came across such _____ bottle on an island in the North Sea.', '["a","an","the","some"]', 0, 'Dùng từ xác định/mạo từ \'a\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_68, '[4] The message in the bottle asked for it to be returned to George Parker Bidder at a scientific association in England along _____ information about where it was found.', '["with","in","on","at"]', 0, 'Sử dụng giới từ \'with\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
