INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_68, '[6] Bidder had once been president of the association and had carried _____ research into ocean currents.', '["in","out","on","at"]', 1, 'Đáp án \'out\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_68, '[7] It appeared that as part of his research he had thrown a thousand bottles into the sea in _____ to help him map the direction of the currents.', '["order","view","case","aim"]', 0, 'Đáp án \'order\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
