INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_69, '[2] They all have large feet and extremely strong back legs as _____ as a long tail, and can grow up to 1.6 metres tall.', '["better","good","well","best"]', 2, 'Đáp án \'well\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_69, '[3] They all have large feet and extremely strong back legs as well as a long tail, and can grow _____ to 1.6 metres tall.', '["in","up","on","at"]', 1, 'Đáp án \'up\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_69, '[4] They tend to jump rather _____ walk because their large feet make walking difficult.', '["than","as","like","so"]', 0, 'Đáp án \'than\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
