INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_69, '[7] Although they may come out of the pocket to play or explore, the pocket is _____ they live for many months after their birth.', '["where","who","whom","whose"]', 0, 'Đại từ quan hệ \'where\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_69, '[8] Kangaroos feed _____ grasses, leaves, flowers and moss.', '["at","in","on","to"]', 2, 'Sử dụng giới từ \'on\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
