INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Uluru/Ayers Rock', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nUluru/Ayers Rock is [1] of Australia’s best-known natural landmarks. It stands in the middle of a desert landscape in central Australia, some 335 kilometres from Alice Springs, [2] nearest large town. The Rock is 348 metres [3] height with a circumference of 9.4 kilometres. It was named [4] Sir Henry Ayers, who was the Chief Secretary of South Australia [5] non-native Australians first saw the Rock.\n\nArchaeological remains indicate that Aboriginals [6] living near the rock over 10,000 years ago. The name they gave to the Rock was Uluru, and in 2002 it was officially renamed Uluru/Ayers Rock.\n\n[7] it is possible to climb onto the Rock, the local Aboriginals prefer people not to [8] so because they regard it [9] a sacred place. They prefer people who visit the rock to walk on a path which goes [10] the way round the Rock.\n\nThe Rock is at its [11] impressive at dawn and sunset, when it glows red.', 'B1', 660, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_71, '[1] Uluru/Ayers Rock is _____ of Australia’s best-known natural landmarks.', '["one","a","an","the"]', 0, 'Đáp án \'one\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_71, '[2] It stands in the middle of a desert landscape in central Australia, some 335 kilometres from Alice Springs, _____ nearest large town.', '["a","the","an","some"]', 1, 'Dùng từ xác định/mạo từ \'the\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_71, '[3] The Rock is 348 metres _____ height with a circumference of 9.4 kilometres.', '["on","in","at","to"]', 1, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_71, '[4] It was named _____ Sir Henry Ayers, who was the Chief Secretary of South Australia when non-native Australians first saw the Rock.', '["since","after","for","during"]', 1, 'Đáp án \'after\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
