INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_71, '[7] _____ it is possible to climb onto the Rock, the local Aboriginals prefer people not to do so because they regard it as a sacred place.', '["Whereas","Even though","Whilst","Although"]', 3, 'Sử dụng liên từ \'Although\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_71, '[8] Although it is possible to climb onto the Rock, the local Aboriginals prefer people not to _____ so because they regard it as a sacred place.', '["did","does","do","doing"]', 2, 'Đáp án \'do\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_71, '[9] Although it is possible to climb onto the Rock, the local Aboriginals prefer people not to do so because they regard it _____ a sacred place.', '["for","because","since","as"]', 3, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_71, '[10] They prefer people who visit the rock to walk on a path which goes _____ the way round the Rock.', '["both","all","each","every"]', 1, 'Dùng từ xác định/mạo từ \'all\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_71, '[11] The Rock is at its _____ impressive at dawn and sunset, when it glows red.', '["more","much","many","most"]', 3, '\'most\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Outdoor swimming', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nEver [1] I was a young girl, I have been an enthusiastic outdoor swimmer. My favourite place to swim is the lido near my home in London – a giant pool with reflections in the sun like jewels. Being unheated, [2] can be uninviting to those [3] prefer warmer water, but that also means fewer crowds. \n\nThe swims I prefer are the ones on my own when I have the pool all to [4] . Then, I slip into the water and feel it surround me. I swim up and down the pool, thinking of nothing [5] than counting strokes between breaths: ‘One, two, three four – breathe.’ Whole hours can slowly drift [6] , as my arms stretch out in [7] of me. I concentrate [8] the noise the bubbles make as I exhale under water. Even when there is the occasional other swimmer, I feel alone and [9] peace, a sensation I don’t get [10] else I know.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
