INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_72, '[2] Being unheated, _____ can be uninviting to those who prefer warmer water, but that also means fewer crowds.', '["it","I","you","he"]', 0, 'Đáp án \'it\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
