INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('The Oscars', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nMany countries have annual awards for outstanding achievements [1] the film industry. By [2] the most famous awards are those made by the American Academy of Motion Picture Arts and Sciences – the Oscars. The name actually refers [3] the statuette which all of the winners receive. The awards do not go only to actors [4] also to other people involved in the production of a film, [5] as make-up artists and costume designers.\n\nNobody knows for certain [6] these awards are called Oscars. There are many theories as to how this came [7] . However, the most widely accepted one concerns Margaret Herrick, the secretary to the Academy; [8] she first saw the statuettes in 1931, her initial reaction was to say that they looked remarkably [9] her cousin Oscar Pierce. He worked on a farm and had [10] at all to do with the film industry.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
