INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_73, '[2] By _____ the most famous awards are those made by the American Academy of Motion Picture Arts and Sciences – the Oscars.', '["near","far","away","distant"]', 1, 'Đáp án \'far\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_73, '[3] The name actually refers _____ the statuette which all of the winners receive.', '["in","to","on","at"]', 1, 'Sử dụng giới từ \'to\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_73, '[4] The awards do not go only to actors _____ also to other people involved in the production of a film, such as make-up artists and costume designers.', '["even though","although","though","but"]', 3, 'Đáp án \'but\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
