INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_73, '[7] There are many theories as to how this came _____ .', '["about","in","on","at"]', 0, 'Sử dụng giới từ \'about\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_73, '[8] However, the most widely accepted one concerns Margaret Herrick, the secretary to the Academy; _____ she first saw the statuettes in 1931, her initial reaction was to say that they looked remarkably like her cousin Oscar Pierce.', '["when","since","for","during"]', 0, 'Đại từ quan hệ \'when\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
