INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('An early science fiction writer', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nThe English writer Herbert George Wells, better known simply [1] H.G.Wells lived from 1866 to 1946. He produced books on a wide range of subjects, including history, politics and social affairs. Despite [2] , he is best remembered now for his books of science fiction. Indeed, along [3] Jules Verne and Hugo Gernsbacher, he is often considered to be [4] of the founding fathers of science fiction.\n\nHis books, [5] as The Invisible Man and The Time Machine, still make good reading. His book, The War of the Worlds, though, is said to have caused panic in the United States [6] it was broadcast as a radio play in 1938. Much of the book consists [7] news bulletins reporting the landing of a spaceship on earth. Many people who switched on the radio after the programme [8] begun did not realise that they were listening to a play; they thought that [9] they were hearing was real and that the world was actually [10] invaded by aliens.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
