INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_74, '[7] Much of the book consists _____ news bulletins reporting the landing of a spaceship on earth.', '["in","of","on","at"]', 1, 'Sử dụng giới từ \'of\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
