INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Nordic walking', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nNordic walking is an outdoor activity first developed in [1] 1930s in Finland. It basically involves walking with very light sticks a bit like ski-poles which are strapped to your wrists and [2] behind you to propel you along.\n\nNordic walking was initially devised [3] a form of summer exercise for winter cross-country skiers, but was not taken seriously [4] the purpose of general fitness training until roughly the turn [5] the century. Since then, [6] popularity has exploded in Europe, and it is taking off in the USA, Australia and Japan.\n\nThe appeal of the activity is obvious. Not [7] is it easy to do, but Nordic walking is apparently the most complete body workout [8] is, using more muscles than either running or swimming. For people who dislike gyms, it is perfect. Nordic walking can be done almost [9] , from beaches and parks [10] city streets.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_75, '[1] Nordic walking is an outdoor activity first developed in _____ 1930s in Finland.', '["the","a","an","some"]', 0, 'Dùng từ xác định/mạo từ \'the\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
