INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_75, '[3] Nordic walking was initially devised _____ a form of summer exercise for winter cross-country skiers, but was not taken seriously for the purpose of general fitness training until roughly the turn of the century.', '["because","as","since","for"]', 1, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_75, '[4] Nordic walking was initially devised as a form of summer exercise for winter cross-country skiers, but was not taken seriously _____ the purpose of general fitness training until roughly the turn of the century.', '["at","in","on","for"]', 3, 'Sử dụng giới từ \'for\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_75, '[5] Nordic walking was initially devised as a form of summer exercise for winter cross-country skiers, but was not taken seriously for the purpose of general fitness training until roughly the turn _____ the century.', '["at","in","on","of"]', 3, 'Sử dụng giới từ \'of\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_75, '[6] Since then, _____ popularity has exploded in Europe, and it is taking off in the USA, Australia and Japan.', '["my","its","your","his"]', 1, 'Đáp án \'its\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_75, '[7] Not _____ is it easy to do, but Nordic walking is apparently the most complete body workout there is, using more muscles than either running or swimming.', '["alone","just","merely","only"]', 3, 'Đáp án \'only\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_75, '[8] Not only is it easy to do, but Nordic walking is apparently the most complete body workout _____ is, using more muscles than either running or swimming.', '["it","there","here","they"]', 1, 'Đáp án \'there\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_75, '[9] Nordic walking can be done almost _____ , from beaches and parks to city streets.', '["somewhere","anywhere","nowhere","in"]', 1, 'Đáp án \'anywhere\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_75, '[10] Nordic walking can be done almost anywhere , from beaches and parks _____ city streets.', '["to","in","on","at"]', 0, 'Sử dụng giới từ \'to\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Laughter', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nPeople will often start to laugh [1] they hear others laughing. Psychologists tell us that this is [2] , in certain circumstances, human beings have a tendency to imitate one [3] . Television producers are well aware of this, which is [4] they make sure that viewers hear laughter at amusing moments in their programmes. The laughter may be genuine, coming from a live audience watching the show.  Often, however, it is [5] is known as ‘canned laughter’ – that is laughter which has been recorded [6] advance and added to the programme after it [7] been made.\n\nUsing laughter to encourage further laughter is by [8] means a new phenomenon; in the nineteenth century, theatre managers would pay somebody [9] had a loud and infectious laugh to sit in the audience. The managers knew that as soon as this person began to laugh, other people in the audience would do so as [10] , thus helping to ensure the success of the show.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_76, '[1] People will often start to laugh _____ they hear others laughing.', '["since","when","for","during"]', 1, 'Đại từ quan hệ \'when\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_76, '[2] Psychologists tell us that this is _____ , in certain circumstances, human beings have a tendency to imitate one another .', '["since","because","as","for"]', 1, 'Sử dụng liên từ \'because\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_76, '[3] Psychologists tell us that this is because , in certain circumstances, human beings have a tendency to imitate one _____ .', '["others","other","another","each other"]', 2, 'Đáp án \'another\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_76, '[4] Television producers are well aware of this, which is _____ they make sure that viewers hear laughter at amusing moments in their programmes.', '["whose","who","whom","why"]', 3, 'Đại từ quan hệ \'why\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_76, '[5] Often, however, it is _____ is known as ‘canned laughter’ – that is laughter which has been recorded in advance and added to the programme after it has been made.', '["who","what","whom","whose"]', 1, 'Đáp án \'what\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_76, '[6] Often, however, it is what is known as ‘canned laughter’ – that is laughter which has been recorded _____ advance and added to the programme after it has been made.', '["in","on","at","to"]', 0, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_76, '[7] Often, however, it is what is known as ‘canned laughter’ – that is laughter which has been recorded in advance and added to the programme after it _____ been made.', '["had","have","has","having"]', 2, 'Đáp án \'has\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_76, '[8] Using laughter to encourage further laughter is by _____ means a new phenomenon; in the nineteenth century, theatre managers would pay somebody who had a loud and infectious laugh to sit in the audience.', '["an","a","no","the"]', 2, 'Đáp án \'no\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_76, '[9] Using laughter to encourage further laughter is by no means a new phenomenon; in the nineteenth century, theatre managers would pay somebody _____ had a loud and infectious laugh to sit in the audience.', '["who","whom","whose","which"]', 0, 'Đại từ quan hệ \'who\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_76, '[10] The managers knew that as soon as this person began to laugh, other people in the audience would do so as _____ , thus helping to ensure the success of the show.', '["better","good","well","best"]', 2, 'Đáp án \'well\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Resolutions', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nAt the start of a new year or [1] their birthday, people in some countries make resolutions for the future. These resolutions are decisions that people make in the hope of changing their lives [2] the better. Resolutions range from giving [3] a bad habit such as smoking [4] beginning a new activity, for example, learning to play a musical instrument.\n\nUnfortunately, many people find keeping their resolutions very difficult and, after a month [5] so, abandon them. This is often a result of [6] set a totally unrealistic goal for themselves.\n\nThe people who are most successful in keeping their resolutions are usually those who make sure that their goals are fairly small and straightforward. They have a clear idea of precisely [7] they plan to do to reach their goal. Often they find [8] helpful if they have friends who have made the same resolution [9] they are then able to support one [10] in remaining committed and focused.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_77, '[1] At the start of a new year or _____ their birthday, people in some countries make resolutions for the future.', '["to","in","at","on"]', 3, 'Sử dụng giới từ \'on\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_77, '[2] These resolutions are decisions that people make in the hope of changing their lives _____ the better.', '["in","for","on","at"]', 1, 'Sử dụng giới từ \'for\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_77, '[3] Resolutions range from giving _____ a bad habit such as smoking to beginning a new activity, for example, learning to play a musical instrument.', '["in","up","on","at"]', 1, 'Đáp án \'up\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_77, '[4] Resolutions range from giving up a bad habit such as smoking _____ beginning a new activity, for example, learning to play a musical instrument.', '["on","in","to","at"]', 2, 'Sử dụng giới từ \'to\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_77, '[5] Unfortunately, many people find keeping their resolutions very difficult and, after a month _____ so, abandon them.', '["so","and","but","or"]', 3, 'Đáp án \'or\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_77, '[6] This is often a result of _____ set a totally unrealistic goal for themselves.', '["having","have","has","had"]', 0, 'Đáp án \'having\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_77, '[7] They have a clear idea of precisely _____ they plan to do to reach their goal.', '["whose","who","whom","what"]', 3, 'Đáp án \'what\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_77, '[8] Often they find _____ helpful if they have friends who have made the same resolution as they are then able to support one another in remaining committed and focused.', '["you","I","it","he"]', 2, 'Đáp án \'it\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_77, '[9] Often they find it helpful if they have friends who have made the same resolution _____ they are then able to support one another in remaining committed and focused.', '["in","for","so","as"]', 3, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_77, '[10] Often they find it helpful if they have friends who have made the same resolution as they are then able to support one _____ in remaining committed and focused.', '["other","another","others","each other"]', 1, 'Đáp án \'another\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Happy Birthday', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nThe song Happy Birthday had [1] origins in 1893, when an American kindergarten teacher, Mildred Hill, and her sister Patty composed a simple song they called Good Morning to All. This was originally intended [2] use by teachers to greet their class [3] day. The Hill sisters could not [4] predicted that children would change the words to become Happy Birthday, a song sung in virtually all languages [5] earth.\n\nAfter a [6] years, the Hill sisters established [7] is called legal copyright for their song. As a [8] of this, anyone using the song can in theory be charged a fee until the copyright expires in 2030. Under the terms of the agreement, the song can still be sung for free on private occasions, as it [9] at countless birthday celebrations. However, the fee is still enforced when the tune is used at large public gatherings, in profit-making enterprises, including movies, or when it is built [10] toys, greeting cards and mobile phones.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_78, '[1] The song Happy Birthday had _____ origins in 1893, when an American kindergarten teacher, Mildred Hill, and her sister Patty composed a simple song they called Good Morning to All.', '["its","my","your","his"]', 0, 'Đáp án \'its\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_78, '[2] This was originally intended _____ use by teachers to greet their class each day.', '["in","for","on","at"]', 1, 'Sử dụng giới từ \'for\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_78, '[3] This was originally intended for use by teachers to greet their class _____ day.', '["either","all","both","each"]', 3, 'Dùng từ xác định/mạo từ \'each\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_78, '[4] The Hill sisters could not _____ predicted that children would change the words to become Happy Birthday, a song sung in virtually all languages on earth.', '["have","has","had","having"]', 0, 'Đáp án \'have\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_78, '[5] The Hill sisters could not have predicted that children would change the words to become Happy Birthday, a song sung in virtually all languages _____ earth.', '["to","in","at","on"]', 3, 'Sử dụng giới từ \'on\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_78, '[6] After a _____ years, the Hill sisters established what is called legal copyright for their song.', '["much","few","many","more"]', 1, '\'few\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_78, '[7] After a few years, the Hill sisters established _____ is called legal copyright for their song.', '["whose","who","whom","what"]', 3, 'Đáp án \'what\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_78, '[8] As a _____ of this, anyone using the song can in theory be charged a fee until the copyright expires in 2030.', '["effect","reason","result","in"]', 2, 'Đáp án \'result\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_78, '[9] Under the terms of the agreement, the song can still be sung for free on private occasions, as it _____ at countless birthday celebrations.', '["was","am","are","is"]', 3, 'Đáp án \'is\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_78, '[10] However, the fee is still enforced when the tune is used at large public gatherings, in profit-making enterprises, including movies, or when it is built _____ toys, greeting cards and mobile phones.', '["on","in","into","at"]', 2, 'Sử dụng giới từ \'into\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Tracking migrating birds', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nThe Arctic tern is a seabird weighing roughly the same [1] a bar of soap. Despite its light weight, the tern flies all the way to the Antarctic and [2] again every year, a distance of 40,000 kilometres [3] it takes the shortest route. However, when researchers equipped terns with satellite tracking devices, they discovered that the birds do not [4] fact take the shortest route. One bird actually flew a distance of up [5] 100,000 kilometres – [6] equivalent of flying more than twice around the earth.\n\n[7] the invention of tracking devices, the only way scientists could track birds was by attaching a ring to a bird’s leg. At best, this allowed them to discover the bird’s destination but gave [8] indication whatsoever of the route it [9] taken to get there. Although tracking devices have certainly increased our knowledge of bird migration, there is still much to be learnt, not least [10] birds manage to navigate their way through the sky.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_79, '[1] The Arctic tern is a seabird weighing roughly the same _____ a bar of soap.', '["for","because","since","as"]', 3, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_79, '[2] Despite its light weight, the tern flies all the way to the Antarctic and _____ again every year, a distance of 40,000 kilometres if it takes the shortest route.', '["out","away","back","again"]', 2, 'Đáp án \'back\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_79, '[3] Despite its light weight, the tern flies all the way to the Antarctic and back again every year, a distance of 40,000 kilometres _____ it takes the shortest route.', '["whether","if","unless","provided"]', 1, 'Sử dụng liên từ \'if\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_79, '[4] However, when researchers equipped terns with satellite tracking devices, they discovered that the birds do not _____ fact take the shortest route.', '["at","on","in","to"]', 2, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_79, '[5] One bird actually flew a distance of up _____ 100,000 kilometres – the equivalent of flying more than twice around the earth.', '["at","in","on","to"]', 3, 'Sử dụng giới từ \'to\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_79, '[6] One bird actually flew a distance of up to 100,000 kilometres – _____ equivalent of flying more than twice around the earth.', '["a","the","an","some"]', 1, 'Dùng từ xác định/mạo từ \'the\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_79, '[7] _____ the invention of tracking devices, the only way scientists could track birds was by attaching a ring to a bird’s leg.', '["Since","Before","For","During"]', 1, 'Đáp án \'Before\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_79, '[8] At best, this allowed them to discover the bird’s destination but gave _____ indication whatsoever of the route it had taken to get there.', '["an","a","no","the"]', 2, 'Đáp án \'no\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_79, '[9] At best, this allowed them to discover the bird’s destination but gave no indication whatsoever of the route it _____ taken to get there.', '["had","have","has","having"]', 0, 'Đáp án \'had\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_79, '[10] Although tracking devices have certainly increased our knowledge of bird migration, there is still much to be learnt, not least _____ birds manage to navigate their way through the sky.', '["what","how","which","where"]', 1, 'Đáp án \'how\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('The Great Escape', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nAn octopus known [1] Inky, kept at the National Aquarium of New Zealand, recently managed to escape from its tank, [2] to the manager there. He believes that security at the aquarium was too tight for anyone to [3] stolen the creature, and that probably it took advantage [4] a small gap in the lid covering its tank, crawling a distance of four metres to a drainpipe [5] led directly to the sea. [6] octopuses have no bones they are able to fit into extremely small spaces [7] much difficulty and, remarkably, have been filmed squeezing into gaps [8] bigger than a coin. In addition, they are thought to be highly intelligent. [9] octopuses have a well-established reputation for attempting escapes from captivity, it was still a surprise for staff to discover that Inky had disappeared. They are now keeping a close eye on their remaining octopus in [10] it tries to do something similar.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_80, '[1] An octopus known _____ Inky, kept at the National Aquarium of New Zealand, recently managed to escape from its tank, according to the manager there.', '["for","because","since","as"]', 3, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_80, '[2] An octopus known as Inky, kept at the National Aquarium of New Zealand, recently managed to escape from its tank, _____ to the manager there.', '["referring","due","owing","according"]', 3, 'Đáp án \'according\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_80, '[3] He believes that security at the aquarium was too tight for anyone to _____ stolen the creature, and that probably it took advantage of a small gap in the lid covering its tank, crawling a distance of four metres to a drainpipe which led directly to the sea.', '["having","has","had","have"]', 3, 'Đáp án \'have\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_80, '[4] He believes that security at the aquarium was too tight for anyone to have stolen the creature, and that probably it took advantage _____ a small gap in the lid covering its tank, crawling a distance of four metres to a drainpipe which led directly to the sea.', '["on","in","of","at"]', 2, 'Sử dụng giới từ \'of\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_80, '[5] He believes that security at the aquarium was too tight for anyone to have stolen the creature, and that probably it took advantage of a small gap in the lid covering its tank, crawling a distance of four metres to a drainpipe _____ led directly to the sea.', '["whom","who","which","whose"]', 2, 'Đại từ quan hệ \'which\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_80, '[6] _____ octopuses have no bones they are able to fit into extremely small spaces without much difficulty and, remarkably, have been filmed squeezing into gaps no bigger than a coin.', '["Until","For","During","Since"]', 3, 'Sử dụng liên từ \'Since\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_80, '[7] Since octopuses have no bones they are able to fit into extremely small spaces _____ much difficulty and, remarkably, have been filmed squeezing into gaps no bigger than a coin.', '["on","in","without","at"]', 2, 'Đáp án \'without\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
