INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_80, '[9] _____ octopuses have a well-established reputation for attempting escapes from captivity, it was still a surprise for staff to discover that Inky had disappeared.', '["Even though","Although","Whilst","Whereas"]', 1, 'Sử dụng liên từ \'Although\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
