INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Strange bones', 'Read the following text and choose the correct answer for each gap [1] - [10]:\n\nUSA farmer James Bristle and his neighbour [1] working in a field when they made a startling discovery. Their digging machine struck [2] hard about two metres underground. They uncovered [3] at first looked like a piece of wood, but [4] out to be an enormous bone over a metre in length. Neither of them [5] ever seen one that size before. Believing [6] to be a dinosaur bone, Bristle immediately [7] in touch with a nearby university, and scientists soon arrived at the farm to investigate. \n\nOver the next few weeks, the team from the university found more bones [8] were almost certainly part of a prehistoric elephant-like creature – a woolly mammoth. Previous findings of mammoth bones in the region have [9] dated at up to twelve thousand years old. However, the scientists say the bones on Bristle’s farm may [10] lain there for fifteen thousand years.', 'B1', 600, 'PUBLISHED', NOW(), NOW());
