INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Yoga improves brain power', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nA recent study [1] appear to prove that yoga has a positive effect on brain activity; [2] so than vigorous exercise.  During the study, a group of volunteers undertook twenty minutes of yoga and twenty minutes of aerobic exercise.  After each session of physical activity, they were asked to perform [3] series of tasks designed to highlight any improvement in their mental abilities.  [4] the surprise of the researchers, the participants showed a significant improvement following yoga practice.  The breathing and meditative exercises in yoga [5] long been known to calm the mind and body and keep distracting thoughts [6] .  But now results showed that participants were better able to focus on tasks, as well as process, hold and update information quickly and accurately.  [7] the aerobic exercise, on the other hand, there seemed to be very [8] positive effect.\n\nThe research suggests that the benefits of yoga go beyond the physical and its implications for the world of work [9] potentially enormous.', 'B2', 540, 'PUBLISHED', NOW(), NOW());
