INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_83, '[2] A recent study would appear to prove that yoga has a positive effect on brain activity; _____ so than vigorous exercise.', '["many","much","more","most"]', 2, '\'more\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
