INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Are you happy where you work?', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nFinding a job you love is the first step to being happy at work, but [1] the right workplace environment is equally important. Creativity, hard work and bright ideas come [2] positive, happy working environments in [3] people are allowed the freedom to think, develop and express themselves. It’s important for everyone to have [4] own clearly-defined work space, even if the workplace adopts an ‘open plan’ style, as so many offices now [5] . Relaxation areas where people meet to chat and discuss ideas during office hours are regarded [6] particularly beneficial.\n\nAdding plants to the working environment can also [7] offices to life, since they increase oxygen levels, purify the air and can create a calming and more productive environment. Finally, the lighting [8] be right, because it can have a huge effect on people’s moods. If offices are too harshly lit, [9] can result in anger and headaches and lead to a lack of concentration.', 'B2', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_84, '[1] Finding a job you love is the first step to being happy at work, but _____ the right workplace environment is equally important.', '["had","have","has","having"]', 3, 'Đáp án \'having\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
