INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Living with lions', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nLions are complicated creatures – wonderful at a distance, [1] fearsomely inconvenient to the rural people [2] fate it is to live among them.\n\nAfrica is home to the world’s lion population. However, surveys suggest that the lion has disappeared from about 80% of its African range. The causes for this [3] multiple, including loss of habitat, poaching and killing of lions by farmers in retaliation [4] livestock losses.\n\nStopping this decline is difficult to deal with.  In Kenya, a new approach is being tried. A programme called ‘Lion Guardians’ recruits young men from the Masai tribe to serve [5] lion protectors. These men are paid and are trained to use GPS technology to track lions [6] a daily basis. The programme aims to prevent lions attacking livestock, which means lions are no [7] in danger of being killed by the farmers. The role of ‘lion guardian’ is now prestigious within the communities. Perhaps this is the best [8] to proceed, in order to help ensure that one of nature’s most magnificent creatures [9] a future.', 'B2', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_85, '[1] Lions are complicated creatures – wonderful at a distance, _____ fearsomely inconvenient to the rural people whose fate it is to live among them.', '["yet","although","though","even though"]', 0, 'Đáp án \'yet\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_85, '[2] Lions are complicated creatures – wonderful at a distance, yet fearsomely inconvenient to the rural people _____ fate it is to live among them.', '["which","who","whom","whose"]', 3, 'Đại từ quan hệ \'whose\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_85, '[3] The causes for this _____ multiple, including loss of habitat, poaching and killing of lions by farmers in retaliation for livestock losses.', '["is","am","are","was"]', 2, 'Đáp án \'are\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_85, '[4] The causes for this are multiple, including loss of habitat, poaching and killing of lions by farmers in retaliation _____ livestock losses.', '["at","in","on","for"]', 3, 'Sử dụng giới từ \'for\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_85, '[5] A programme called ‘Lion Guardians’ recruits young men from the Masai tribe to serve _____ lion protectors.', '["for","because","since","as"]', 3, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
