INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('The Post-it note', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nIt has been described [1] the solution to a problem nobody realised existed.  But that hasn’t stopped the self-attaching Post-it note – that little square piece of paper that sticks in [2] a clever way that it can be removed, leaving no damage – [3] becoming an essential piece of stationery worldwide.\n\n[4] so many other simple inventions, the Post-it note was invented by accident.  A scientist working for a US company was attempting to develop a super-strong adhesive,   [5] instead came up with a super-weak one.  It was just strong [6] to stick light objects together.   What was special about it was that the objects could be separated [7] leaving a mark.  [8] five years, he tried convincing his bosses of the importance of his invention.  Sadly, nobody [9] find a use for it.  Then a colleague noticed that bookmarks in his book kept falling out, and he was continually losing his place.  Remembering the work of this colleague, the scientist set about designing a reusable bookmark using the super-weak adhesive and the Post-it note was born.', 'B2', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_86, '[1] It has been described _____ the solution to a problem nobody realised existed.', '["for","because","since","as"]', 3, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_86, '[2] But that hasn’t stopped the self-attaching Post-it note – that little square piece of paper that sticks in _____ a clever way that it can be removed, leaving no damage – from becoming an essential piece of stationery worldwide.', '["too","very","such","so"]', 2, 'Đáp án \'such\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
