INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_86, '[6] It was just strong _____ to stick light objects together.', '["enough","very","too","so"]', 0, 'Đáp án \'enough\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_86, '[7] What was special about it was that the objects could be separated _____ leaving a mark.', '["on","in","without","at"]', 2, 'Đáp án \'without\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
