INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_87, '[2] _____ a rainy day, they give us exactly the right kind of pleasure.', '["on","in","at","to"]', 0, 'Sử dụng giới từ \'on\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_87, '[3] ‘Books provide people _____ the opportunity for social connection and the joy of being part of something larger than oneself for a few moments,’ according to a recent study.', '["at","in","on","with"]', 3, 'Sử dụng giới từ \'with\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_87, '[4] ‘Books provide people with the opportunity for social connection and the joy of being part of something larger than oneself for a _____ moments,’ according to a recent study.', '["more","much","many","few"]', 3, '\'few\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
