INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_87, '[7] And a ‘comfort’ read book is _____ that’s capable of being read over and over again.', '["an","a","one","the"]', 2, 'Đáp án \'one\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
