INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Walking – the best exercise', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nExercise researchers at Edinburgh University have discovered that British people walk [1] average 120km less per year than they [2] just a decade ago. Experts recommend that people should walk [3] 10,000 and 12,000 steps a day to stay healthy, but if their figures [4] to be believed, the [5] of British people only manage 3,000. Naturally, this concerns the researchers, who point out the wide range of physical and mental health benefits to people of all ages.\n\nFor people who want to take things [6] stage further and use walking as a keep-fit activity, much information is now available online on walking technique; and new exercise concepts like ‘speed walking’ and ‘power walking’ have become popular. According to these sources, it is important to relax the shoulders and keep them down, to swing the arms in time [7] the stride and to lean forward slightly from the ankles. Also, in [8] to increase walking speed, it is advised to concentrate on frequency of steps made as opposed [9] length of stride.', 'B2', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_88, '[1] Exercise researchers at Edinburgh University have discovered that British people walk _____ average 120km less per year than they did just a decade ago.', '["to","in","at","on"]', 3, 'Sử dụng giới từ \'on\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
