INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_88, '[3] Experts recommend that people should walk _____ 10,000 and 12,000 steps a day to stay healthy, but if their figures are to be believed, the majority of British people only manage 3,000.', '["on","in","between","at"]', 2, 'Sử dụng giới từ \'between\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
