INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_89, '[2] In fact, the history of materials can be described _____ a history of accidents, but this is not as catastrophic as it sounds.', '["as","because","since","for"]', 0, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
