INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_89, '[8] _____ the history of materials is any guide, how we eventually use them will, in part, be discovered accidentally.', '["Unless","Whether","If","Provided"]', 2, 'Sử dụng liên từ \'If\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
