INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Green basilisk lizards', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nGreen basilisk lizards, also known [1] plumed or double-crested lizards have an amazing ability to run on water. They are abundant [2] the tropical rainforests of Central America, [3] they spend much of their time up trees and are never that [4] from water.\n\nWhen threatened, they can drop from a tree and sprint at [5] speed of about 1.5 metres per second across the surface of the water. To accomplish this, on their rear feet they have long toes [6] folds of skin that spread out in the water to create a sort of paddle. [7] they are able to maintain their speed, this fold of skin prevents them from sinking. Interestingly, they are born [8] only with the ability to run on land and water but also to climb and swim.\n\nGreen basilisks are omnivores and survive [9] a diet of plant material, fruit, insects and small vertebrates, and are a common sight in the Central American forests.', 'B2', 540, 'PUBLISHED', NOW(), NOW());
