INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_91, '[2] They are abundant _____ the tropical rainforests of Central America, where they spend much of their time up trees and are never that far from water.', '["in","on","at","to"]', 0, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
