INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_96, '[2] Most of the children, _____ , watched fascinated as a bee catcher rounded up the uninvited visitors.', '["although","however","even though","while"]', 1, 'Sử dụng liên từ \'however\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
