INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Dogs understand what you’re saying', 'Read the following text and choose the correct answer for each gap [1] - [12]:\n\nScientists have found evidence that, [1] from being ignorant animals, dogs can understand some of what people say. Researchers carried [2] scans on dogs’ brains as the dogs listened to their trainers speaking. This was to determine [3] or not dogs actively process human speech and, if [4] , which parts of the brain they use. \n\n[5] their amazement, they found that dogs processed words with the left hemisphere of their brain [6] simultaneously processing tone of voice with the right hemisphere. This is consistent [7] the pattern in humans. What’s [8] , the dogs only registered that they were being praised if both words and tone were positive. As [9] rule, meaningless words spoken in encouraging tones, or meaningful words delivered neutrally, had [10] effect, as any dog owner will verify,  than when the speaker was giving approval naturally.\n\nResearchers now wonder if dogs’ mental ability to [11] sense of language means that other animals may have these skills. However, testing this in animals with no inherent interest in human speech will be [12] easy task.', 'B2', 720, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[1] Scientists have found evidence that, _____ from being ignorant animals, dogs can understand some of what people say.', '["far","near","away","distant"]', 0, 'Đáp án \'far\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[2] Researchers carried _____ scans on dogs’ brains as the dogs listened to their trainers speaking.', '["in","out","on","at"]', 1, 'Đáp án \'out\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[3] This was to determine _____ or not dogs actively process human speech and, if so , which parts of the brain they use.', '["unless","if","whether","provided"]', 2, 'Sử dụng liên từ \'whether\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[4] This was to determine whether or not dogs actively process human speech and, if _____ , which parts of the brain they use.', '["since","because","so","as"]', 2, 'Sử dụng liên từ \'so\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[5] _____ their amazement, they found that dogs processed words with the left hemisphere of their brain while simultaneously processing tone of voice with the right hemisphere.', '["At","In","On","To"]', 3, 'Sử dụng giới từ \'To\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[6] To their amazement, they found that dogs processed words with the left hemisphere of their brain _____ simultaneously processing tone of voice with the right hemisphere.', '["during","since","for","while"]', 3, 'Sử dụng liên từ \'while\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[7] This is consistent _____ the pattern in humans.', '["at","in","on","with"]', 3, 'Sử dụng giới từ \'with\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[8] What’s _____ , the dogs only registered that they were being praised if both words and tone were positive.', '["more","much","many","most"]', 0, '\'more\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[9] As _____ rule, meaningless words spoken in encouraging tones, or meaningful words delivered neutrally, had less effect, as any dog owner will verify, than when the speaker was giving approval naturally.', '["the","an","a","some"]', 2, 'Dùng từ xác định/mạo từ \'a\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[10] As a rule, meaningless words spoken in encouraging tones, or meaningful words delivered neutrally, had _____ effect, as any dog owner will verify, than when the speaker was giving approval naturally.', '["many","much","less","more"]', 2, '\'less\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[11] Researchers now wonder if dogs’ mental ability to _____ sense of language means that other animals may have these skills.', '["have","do","take","make"]', 3, 'Đáp án \'make\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_99, '[12] However, testing this in animals with no inherent interest in human speech will be _____ easy task.', '["an","a","no","the"]', 2, 'Đáp án \'no\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Physical exercise is good for the brain', 'Read the following text and choose the correct answer for each gap [1] - [12]:\n\nLiteracy and numeracy activities like word and number puzzles are often considered better for our brains [1] running and jumping. However, recent experiments show that contrary [2] popular belief, not only mental [3] also physical activity can have profound effects [4] our brains. In a series of experiments, involving people of various ages, brain structure has in actual [5] been proven to grow as people become fitter.\n\nLearning things [6] simultaneously doing moderate exercise helped students retain the information. Switching between periods of mental activity and aerobics also increased attention span. In another experiment, elderly people participated [7] weekly dance classes for six months. Even [8] they worked hard, their aerobic capacity changed very [9] ; on the other hand, their cognitive skills improved considerably.\n\nThis research reminds us that physical activity and our brains are linked. Sitting still is not to [10] recommended, and in a similar way, [11] is spending considerable time weighing [12] which exercise to do. Experts recommend finding an exercise you enjoy, doing it and gaining the benefits.', 'B2', 720, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_100, '[1] Literacy and numeracy activities like word and number puzzles are often considered better for our brains _____ running and jumping.', '["as","than","like","so"]', 1, 'Đáp án \'than\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_100, '[2] However, recent experiments show that contrary _____ popular belief, not only mental but also physical activity can have profound effects on our brains.', '["to","in","on","at"]', 0, 'Sử dụng giới từ \'to\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_100, '[3] However, recent experiments show that contrary to popular belief, not only mental _____ also physical activity can have profound effects on our brains.', '["though","although","but","even though"]', 2, 'Đáp án \'but\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_100, '[4] However, recent experiments show that contrary to popular belief, not only mental but also physical activity can have profound effects _____ our brains.', '["at","in","on","to"]', 2, 'Sử dụng giới từ \'on\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
