INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_100, '[6] Learning things _____ simultaneously doing moderate exercise helped students retain the information.', '["during","since","for","while"]', 3, 'Sử dụng liên từ \'while\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_100, '[7] In another experiment, elderly people participated _____ weekly dance classes for six months.', '["on","in","at","to"]', 1, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_100, '[8] Even _____ they worked hard, their aerobic capacity changed very little ; on the other hand, their cognitive skills improved considerably.', '["even though","although","though","while"]', 2, 'Sử dụng liên từ \'though\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
