INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Winter fingerprints and your smartphone', 'Read the following text and choose the correct answer for each gap [1] - [12]:\n\nWhen it comes [1] modern gadgets our enjoyment of them can be short-lived. It’s some time [2] we got excited about phones with fingerprint scanners; then we were let [3] when they proved to be unreliable.\n\nImagine the situation: you’re outside in the winter and you want to unlock your phone. So, [4] you do is place your finger on the sensor once, twice, three times [5] any success whatsoever, then give up and enter the code instead. The explanation is that cold weather alters your fingerprint to make [6] unrecognizable. The cold can make the ridges in your skin stiffer, but [7] often than not, it’s a matter of your skin [8] made drier and rougher, [9] of which affect your fingerprint. \n\nMysteriously, though, the cold weather problem can occur indoors too and [10] amount of drying or cleaning your fingertips will solve it. Unfortunately, fingerprint recognition is hampered by a range of things, [11] the condition of your skin to the use of lotions.\n\nFortunately, there are solutions; the simplest by [12] is to keep your hands summery and youthful!', 'B2', 720, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_101, '[1] When it comes _____ modern gadgets our enjoyment of them can be short-lived.', '["at","in","on","to"]', 3, 'Sử dụng giới từ \'to\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_101, '[2] It’s some time _____ we got excited about phones with fingerprint scanners; then we were let down when they proved to be unreliable.', '["until","for","during","since"]', 3, 'Sử dụng liên từ \'since\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
