INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_101, '[4] So, _____ you do is place your finger on the sensor once, twice, three times without any success whatsoever, then give up and enter the code instead.', '["what","who","whom","whose"]', 0, 'Đáp án \'what\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_101, '[5] So, what you do is place your finger on the sensor once, twice, three times _____ any success whatsoever, then give up and enter the code instead.', '["without","in","on","at"]', 0, 'Đáp án \'without\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_101, '[6] The explanation is that cold weather alters your fingerprint to make _____ unrecognizable.', '["it","I","you","he"]', 0, 'Đáp án \'it\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
