INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Background music while you shop', 'Read the following text and choose the correct answer for each gap [1] - [13]:\n\nWhat are your feelings about [1] subjected to background music in shops? Is it harmless noise or something you’d [2] was turned off? \n\nResearch suggests that this music may have a significant impact [3] sales; for instance it has [4] shown to influence the speed at [5] customers shop and what they buy. In fact, it’s likely to affect [6] the customer does, from the amount they are thinking of spending [7] how long they think they have spent in the shop.\n\nDifferent types of music have different effects, with classical music encouraging greater spending, while slow music encourages slower (and longer) shopping. Choosing the kind of music to play is not simple; some music carries strong associations and there’s [8] guarantee these will be positive for customers.  Consequently most stores end [9] with something bland.  \n\nIn shops [10] silence has replaced music, people sense that something is different, but don’t immediately know [11] has changed. However, the overwhelming reaction is relief [12] not having to talk [13] noise anymore.', 'B2', 780, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_102, '[1] What are your feelings about _____ subjected to background music in shops?', '["is","am","being","are"]', 2, 'Đáp án \'being\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_102, '[2] Is it harmless noise or something you’d _____ was turned off?', '["rather","very","too","so"]', 0, 'Đáp án \'rather\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
