INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Human body rhythms', 'Read the following text and choose the correct answer for each gap [1] - [12]:\n\nI’m a scientist and I study human body rhythms, [1] circadian rhythms as they are called. Everything in our body is rhythmic; we used to think that there was just one ‘clock’ in the brain controlling these rhythms, [2] we now know that we have clocks in just about [3] tissue in our body. We are trying to understand [4] they interact with one another and the way they are affected by time cues [5] light or meal times. Scientists study these rhythms [6] we can help people, for example, to synchronise to new time zones and also help those [7] circadian rhythms are out of balance. \n\n[8] currently interests me is the link [9] the timing of our clocks and our metabolism. We know, for example, that long-term shift workers seem to desire sugary things such as biscuits and this can lead [10] health problems. Why [11] is the case requires a lot more research. My colleagues and I are working [12] finding a link at the moment.', 'B2', 720, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_103, '[1] I’m a scientist and I study human body rhythms, _____ circadian rhythms as they are called.', '["so","and","but","or"]', 3, 'Đáp án \'or\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
