INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_103, '[4] We are trying to understand _____ they interact with one another and the way they are affected by time cues like light or meal times.', '["where","what","which","how"]', 3, 'Đáp án \'how\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
