INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Work experience abroad', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nEvery year thousands [1] young people in various countries do short periods of work in other countries [2] the time they leave school and start university.  Typically these involve helping in schools or hospitals, or on conservation projects.  The experience the young people gain will be of great benefit in their lives.  [3] a personal point of view, it gives them a sense of independence and confidence.  It may also help them with their long-term career.\n\nThere are many organisations that run work experience programmes.  [4] such company is Global Volunteers, [5] spokesperson Mary Cooper comments: ‘[6] than being an extended holiday, our placements involve learning to [7] responsibility for themselves.  Young people should push themselves out of their comfort zones and do [8] productive.  Doing a placement will add value to a CV, helping young people to [9] out from the crowd in the job market.  Some employers look favourably on students who have the initiative and drive to complete one.’', 'B2', 540, 'PUBLISHED', NOW(), NOW());
