INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Handwriting', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nAbout six months ago, I realised I had [1] idea what the handwriting of a good friend of mine looked like.  We had always communicated by email and text but never by a handwritten letter.  And it struck me that we are at a moment [2] handwriting seems to be about to vanish from our lives altogether.  [3] some point in recent years, it stopped [4] a necessary and inevitable intermediary between people – a means by [5] individuals communicate with each other, putting a little bit of their personality [6] the form of the message as they press the ink-bearing point onto the paper.  It has started to become just [7] among many options, often considered unattractive and elaborate.\n\nFor each of us, the act of putting marks on paper with ink goes back as [8] as we can remember.  Our handwriting, like ourselves, seems always to have been there.  But now, given that most of us communicate via email and text, have we lost [9] crucial to the human experience?', 'B2', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_107, '[1] About six months ago, I realised I had _____ idea what the handwriting of a good friend of mine looked like.', '["the","a","an","no"]', 3, 'Đáp án \'no\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_107, '[2] And it struck me that we are at a moment _____ handwriting seems to be about to vanish from our lives altogether.', '["for","since","when","during"]', 2, 'Đại từ quan hệ \'when\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_107, '[3] _____ some point in recent years, it stopped being a necessary and inevitable intermediary between people – a means by which individuals communicate with each other, putting a little bit of their personality in the form of the message as they press the ink-bearing point onto the paper.', '["In","At","On","To"]', 1, 'Sử dụng giới từ \'At\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
