INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_107, '[5] At some point in recent years, it stopped being a necessary and inevitable intermediary between people – a means by _____ individuals communicate with each other, putting a little bit of their personality in the form of the message as they press the ink-bearing point onto the paper.', '["whom","who","which","whose"]', 2, 'Đại từ quan hệ \'which\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_107, '[6] At some point in recent years, it stopped being a necessary and inevitable intermediary between people – a means by which individuals communicate with each other, putting a little bit of their personality _____ the form of the message as they press the ink-bearing point onto the paper.', '["in","on","at","to"]', 0, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_107, '[7] It has started to become just _____ among many options, often considered unattractive and elaborate.', '["an","a","one","the"]', 2, 'Đáp án \'one\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_107, '[8] For each of us, the act of putting marks on paper with ink goes back as _____ as we can remember.', '["distant","near","away","far"]', 3, 'Đáp án \'far\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
