INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Working at the right temperature', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nKeeping an office at a comfortable temperature [1] everyone who works in it is virtually impossible, since ‘comfortable’ means [2] different to everyone.  Temperature wars at the office are a common problem.  It’s [3] unheard of for employees to sneak to the thermostat to change it to [4] liking while others aren’t looking.  And if you think there’s a gender divide in your office, then you’re right.  Muscle insulates, so men, on account of [5] more muscular, tend to feel warmer than women.\n\nHowever, seen [6] the perspective of the employer, there’s more [7] it than just comfort.  Studies show that the temperature in a workplace also affects productivity.  Common sense would suggest that cooling people down makes them work harder, [8] research shows that the opposite is actually true.  When people are cold, they do less work and make more mistakes.\n\nSo is there any hope of finding the perfect temperature?  Probably not, until technology reaches a point [9] companies can set the temperature for each individual workspace.', 'B2', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_108, '[1] Keeping an office at a comfortable temperature _____ everyone who works in it is virtually impossible, since ‘comfortable’ means something different to everyone.', '["for","in","on","at"]', 0, 'Sử dụng giới từ \'for\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_108, '[2] Keeping an office at a comfortable temperature for everyone who works in it is virtually impossible, since ‘comfortable’ means _____ different to everyone.', '["nothing","anything","everything","something"]', 3, 'Đáp án \'something\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
