INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Sleep deprivation on Mars mission', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nGetting enough sleep will be [1] of the biggest challenges facing astronauts on a manned mission to Mars, according to a recent study.  Six would-be astronauts spent 18 months together in a sealed building [2] access to natural light, fresh air or face-to-face contact with [3] other human beings during a simulated trip to the planet.\n\nResearch [4] how each man coped revealed wide differences in [5] respective wake-sleep patterns.  The lack of natural light meant that the men [6] not tell when it was night time.  One man’s daily rhythm shifted from a 24-hour period to a 25-hour one, [7] meant that on every 24th day his body told [8] it was midnight when it was actually midday.  And while most of the crew began to sleep for longer periods [9] the mission went on and boredom set in, one individual slept progressively less until he became seriously sleep-deprived.  Only one man had the right sleep pattern – staying active by day and sleeping well at night.', 'B2', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_109, '[1] Getting enough sleep will be _____ of the biggest challenges facing astronauts on a manned mission to Mars, according to a recent study.', '["one","a","an","the"]', 0, 'Đáp án \'one\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_109, '[2] Six would-be astronauts spent 18 months together in a sealed building _____ access to natural light, fresh air or face-to-face contact with any other human beings during a simulated trip to the planet.', '["in","without","on","at"]', 1, 'Đáp án \'without\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_109, '[3] Six would-be astronauts spent 18 months together in a sealed building without access to natural light, fresh air or face-to-face contact with _____ other human beings during a simulated trip to the planet.', '["an","a","any","the"]', 2, 'Dùng từ xác định/mạo từ \'any\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_109, '[4] Research _____ how each man coped revealed wide differences in their respective wake-sleep patterns.', '["into","in","at","to"]', 0, 'Sử dụng giới từ \'into\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
