INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_109, '[7] One man’s daily rhythm shifted from a 24-hour period to a 25-hour one, _____ meant that on every 24th day his body told him it was midnight when it was actually midday.', '["which","who","whom","whose"]', 0, 'Đại từ quan hệ \'which\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_109, '[8] One man’s daily rhythm shifted from a 24-hour period to a 25-hour one, which meant that on every 24th day his body told _____ it was midnight when it was actually midday.', '["her","me","you","him"]', 3, 'Đại từ \'him\' giữ đúng vai trò ngữ pháp (tân ngữ/sở hữu/phản thân) trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_109, '[9] And while most of the crew began to sleep for longer periods _____ the mission went on and boredom set in, one individual slept progressively less until he became seriously sleep-deprived.', '["for","because","since","as"]', 3, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Star-gazing', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nFew sights are as thrilling [1] a sky full of stars, but if you want to become a serious star-gazer you might need some help.  First, let your eyes adjust to the dark before going outside.  That means not just going out directly [2] staring at a computer screen.  Wait for the clearest [3] nights and find a viewing point [4] light pollution is at a minimum.  A red light is better for viewing your star map [5] the bright blue-white LED of a torch; for [6] reason a rear cycle light is useful.  You’ll find you can look at the map and then look up at the real thing [7] much trouble.\n\nIt may seem obvious, [8] the first thing to do is work out the direction in [9] you’re facing.  Then begin by naming one easily-found star, and work from there.  Pretty soon you start to recognise the sky’s equivalent of landmarks and you’ll find that even stars and planets have their distinguishing features.', 'B2', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_110, '[1] Few sights are as thrilling _____ a sky full of stars, but if you want to become a serious star-gazer you might need some help.', '["for","because","since","as"]', 3, 'Sử dụng liên từ \'as\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_110, '[2] That means not just going out directly _____ staring at a computer screen.', '["during","since","for","after"]', 3, 'Đáp án \'after\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_110, '[3] Wait for the clearest _____ nights and find a viewing point where light pollution is at a minimum.', '["in","of","on","at"]', 1, 'Sử dụng giới từ \'of\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_110, '[4] Wait for the clearest of nights and find a viewing point _____ light pollution is at a minimum.', '["who","where","whom","whose"]', 1, 'Đại từ quan hệ \'where\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
