INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Doodling is good', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nThe next time you are caught doodling, that is making unconscious or unfocused drawings [1] you should be listening, declare that you are simply trying to boost your concentration. Recent research suggests that, [2] than something to be frowned on, doodling should be actively encouraged because it improves our ability to pay attention. A study which compared [3] well people remembered details of a dull speech found that people who doodled throughout retained much more information than those trying to concentrate on listening.\n\nDoodling, however, is not the same as daydreaming. It is quite common [4] people to start daydreaming when they are stuck in a boring lecture [5] listening to a tedious discussion, and then to pay little attention to what is [6] on around them. But the research suggests that doodling should no [7] be considered an unnecessary distraction. Not [8] is doodling sufficient to stop daydreaming without affecting our task performance, it may actually help keep us [9] track with a boring task.', 'B2', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_111, '[1] The next time you are caught doodling, that is making unconscious or unfocused drawings _____ you should be listening, declare that you are simply trying to boost your concentration.', '["since","when","for","during"]', 1, 'Đại từ quan hệ \'when\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_111, '[2] Recent research suggests that, _____ than something to be frowned on, doodling should be actively encouraged because it improves our ability to pay attention.', '["rather","very","too","so"]', 0, 'Đáp án \'rather\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
