INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_111, '[4] It is quite common _____ people to start daydreaming when they are stuck in a boring lecture or listening to a tedious discussion, and then to pay little attention to what is going on around them.', '["at","in","on","for"]', 3, 'Sử dụng giới từ \'for\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
