INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Widening our horizons', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nNew research shows that getting away, and it doesn’t even [1] where we’re going, is an essential prerequisite for problem solving. The reason is that with problems that feel ‘close’ – [2] of whether this closeness is physical, temporal or even emotional – our thoughts are constricted and bound by a more limited set of associations, and as a [3] our imagination is inhibited. When we escape from familiar surroundings, the mind is [4] of a sudden made aware of the original ideas we are [5] the habit of suppressing, and we start thinking about any number of obscure possibilities that would never have occurred to us at home. \n\nBut this is by [6] means the only psychological advantage of travel. Researchers found that students who had lived abroad for some time were a [7] deal more likely to be [8] of solving complex puzzles quickly. Seasoned travellers are, to some [9] , more willing to realise that there are different, but nevertheless equally valid, ways of interpreting the world.', 'C1', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_112, '[1] New research shows that getting away, and it doesn’t even _____ where we’re going, is an essential prerequisite for problem solving.', '["issue","problem","trouble","matter"]', 3, 'Đáp án \'matter\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_112, '[2] The reason is that with problems that feel ‘close’ – _____ of whether this closeness is physical, temporal or even emotional – our thoughts are constricted and bound by a more limited set of associations, and as a result our imagination is inhibited.', '["regardless","despite","careless","in"]', 0, 'Đáp án \'regardless\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_112, '[3] The reason is that with problems that feel ‘close’ – regardless of whether this closeness is physical, temporal or even emotional – our thoughts are constricted and bound by a more limited set of associations, and as a _____ our imagination is inhibited.', '["reason","result","effect","in"]', 1, 'Đáp án \'result\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_112, '[4] When we escape from familiar surroundings, the mind is _____ of a sudden made aware of the original ideas we are in the habit of suppressing, and we start thinking about any number of obscure possibilities that would never have occurred to us at home.', '["every","both","each","all"]', 3, 'Dùng từ xác định/mạo từ \'all\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_112, '[5] When we escape from familiar surroundings, the mind is all of a sudden made aware of the original ideas we are _____ the habit of suppressing, and we start thinking about any number of obscure possibilities that would never have occurred to us at home.', '["to","on","at","in"]', 3, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_112, '[6] But this is by _____ means the only psychological advantage of travel.', '["No","A","An","The"]', 0, 'Đáp án \'No\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
