INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_113, '[2] Many of us have friends _____ handwriting is unfamiliar to us because we have never seen it.', '["which","who","whom","whose"]', 3, 'Đại từ quan hệ \'whose\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_113, '[3] This is _____ to say that we should forgo all the advantages of electronic communication, but what it has led to is that some British schools no longer teach handwriting, on the grounds that all children now have access to computers.', '["never","no","not","none"]', 2, 'Đáp án \'not\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
