INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_113, '[7] While some feel this is _____ too far, it is also true that because every individual has a distinctive style, handwriting is, in all probability, expressing something about them.', '["going","coming","heading","moving"]', 0, 'Đáp án \'going\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
