INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_115, '[3] Traffic lights and road signs would no _____ be needed.', '["more","longer","further","farther"]', 1, 'Đáp án \'longer\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_115, '[4] Different autonomous vehicles on the road would be able to coordinate their movements, and travel _____ close formation, so that traffic would be kept flowing without interruption, making journeys quicker and road use more efficient.', '["at","on","in","to"]', 2, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
