INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Paper is here to stay', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nMany experts argue that, [1] of recent technological changes, paper will remain by [2] the most ubiquitous, useful and easily recyclable medium of communication. Indeed, paper is still what most modern forms of communication seek to imitate. After all, even a document on a computer screen resembles a sheet of fresh white paper!\n\nAlmost everything has, at one time or [3] , been made from paper. Strange [4] it may seem, in the nineteenth century paper was used to make wheels on trains, and in the same period, just about every household item could be made from cheap paper. It was also the means by [5] we shaped our identity and [6] question enhanced our lives, thanks to diaries, scrapbooks, photographs and other mementoes. It made us memorable but also, in a [7] of seconds, erasable and dispensable.\n\nFor some, however, there is simply [8] denying that paper is now an anachronism. This seems mistaken, [9] that consumption of paper is still increasing, not decreasing, and that environmentally-friendly alternatives to current production methods are being adopted.', 'C1', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_116, '[1] Many experts argue that, _____ of recent technological changes, paper will remain by far the most ubiquitous, useful and easily recyclable medium of communication.', '["careless","irrespective","despite","regardless"]', 3, 'Đáp án \'regardless\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_116, '[2] Many experts argue that, regardless of recent technological changes, paper will remain by _____ the most ubiquitous, useful and easily recyclable medium of communication.', '["near","far","away","distant"]', 1, 'Đáp án \'far\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
