INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_116, '[7] It made us memorable but also, in a _____ of seconds, erasable and dispensable.', '["problem","matter","trouble","issue"]', 1, 'Đáp án \'matter\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
