INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_117, '[3] A poor translation might merely cause amusement, but at _____ , the consequences could sometimes be extremely serious.', '["worst","worse","bad","least"]', 0, 'Đáp án \'worst\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
