INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('The joy of shops', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nOne of my favourite columnists has joined the ranks of those [1] think it’s only a [2] of time before shops die [3] altogether and we acquire everything online. [4] all due respect, I say he is wrong since he doesn’t seem to realise that real shopping is [5] partly about acquiring things. You can – at [6] some people can – have a highly satisfactory afternoon shopping [7] buying a thing. This is in no way amazing; fishing, after [8] , doesn’t depend on bringing home supper. The keenest fisherman I know invariably puts the fish back in the water.\n\nIn a similar way, evening classes may or may not achieve their original objective – better command of a foreign language perhaps – [9] they provide companionship and a pleasant evening out. The process of acquiring something is very often more important than the thing acquired, and so it is with shopping.', 'C1', 540, 'PUBLISHED', NOW(), NOW());
