INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Is nothing impossible?', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nIt is certainly the case that believers in ‘nothing is impossible’ base their blind optimism [1] a kernel of truth. Strictly [2] , as logicians are keen to remind us,  only [3] which involves a logical contradiction is impossible.  So two plus two cannot equal five, [4] can there ever be any truly square circles.  However, the limits that most of us have in [5] when we worry about our lives are rarely logical.\n\nFor as [6] as something remains logically possible, some people can’t help [7] wonder if their dream might become reality. This is exacerbated by the fact that our culture encourages people to [8] big and believe that ‘impossibility’ is nothing more than the creation of a negative mind.\n\nIt is far simpler, though, to concentrate on levels of difficulty and chances of success.  If the former are too high and the latter too low, there’s hardly any point in adding ‘but it isn’t impossible, [9] enough desire or support’.', 'C1', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_119, '[1] It is certainly the case that believers in ‘nothing is impossible’ base their blind optimism _____ a kernel of truth.', '["to","in","at","on"]', 3, 'Sử dụng giới từ \'on\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_119, '[2] Strictly _____ , as logicians are keen to remind us, only that which involves a logical contradiction is impossible.', '["saying","talking","speaking","telling"]', 2, 'Đáp án \'speaking\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_119, '[3] Strictly speaking , as logicians are keen to remind us, only _____ which involves a logical contradiction is impossible.', '["those","this","these","that"]', 3, 'Đại từ quan hệ \'that\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_119, '[4] So two plus two cannot equal five, _____ can there ever be any truly square circles.', '["or","and","but","nor"]', 3, 'Đáp án \'nor\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_119, '[5] However, the limits that most of us have in _____ when we worry about our lives are rarely logical.', '["head","mind","heart","memory"]', 1, 'Đáp án \'mind\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_119, '[6] For as _____ as something remains logically possible, some people can’t help but wonder if their dream might become reality.', '["wide","far","long","deep"]', 2, 'Đáp án \'long\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_119, '[7] For as long as something remains logically possible, some people can’t help _____ wonder if their dream might become reality.', '["though","although","but","even though"]', 2, 'Đáp án \'but\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_119, '[8] This is exacerbated by the fact that our culture encourages people to _____ big and believe that ‘impossibility’ is nothing more than the creation of a negative mind.', '["believe","think","consider","know"]', 1, 'Đáp án \'think\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_119, '[9] If the former are too high and the latter too low, there’s hardly any point in adding ‘but it isn’t impossible, _____ enough desire or support’.', '["considering","provided","given","assuming"]', 2, 'Đáp án \'given\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Mission to Mars', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nWanted: a middle-aged, married couple [1] a 501-day round trip to Mars.  Applicants must be physically and emotionally robust.\n\nThis will be the profile of the very first Martian astronauts if multi-millionaire Dennis Tito’s plans to launch a capsule on 5 January 2018 actually [2] to fruition.  The capsule will take the crew to about 160km above Mars.  The spacecraft will use the gravity of Mars to allow it to return to Earth without burning any more fuel, for fuel efficiency is a priority – the 2018 deadline has been fixed [3] the next launch window when Mars and Earth align again isn’t [4] 2031.\n\nIt’s a [5] order, but the race is on to develop systems involving totally new technologies. [6] that these can be put in place soon enough, the spacecraft might just [7] it.  But even if it [8] leaves Earth, the efforts to achieve these ambitious goals will not be in [9] , as they will lead to valuable advances for future missions.', 'C1', 540, 'PUBLISHED', NOW(), NOW());
