INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_120, '[2] This will be the profile of the very first Martian astronauts if multi-millionaire Dennis Tito’s plans to launch a capsule on 5 January 2018 actually _____ to fruition.', '["arrive","go","come","reach"]', 2, 'Đáp án \'come\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_120, '[3] The spacecraft will use the gravity of Mars to allow it to return to Earth without burning any more fuel, for fuel efficiency is a priority – the 2018 deadline has been fixed _____ the next launch window when Mars and Earth align again isn’t until 2031.', '["so","for","because","in"]', 2, 'Sử dụng liên từ \'because\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_120, '[4] The spacecraft will use the gravity of Mars to allow it to return to Earth without burning any more fuel, for fuel efficiency is a priority – the 2018 deadline has been fixed because the next launch window when Mars and Earth align again isn’t _____ 2031.', '["since","until","for","during"]', 1, 'Đáp án \'until\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
