INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_120, '[6] _____ that these can be put in place soon enough, the spacecraft might just make it.', '["Unless","If","Whether","Supposing"]', 3, 'Đáp án \'Supposing\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
