INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_120, '[8] But even if it _____ leaves Earth, the efforts to achieve these ambitious goals will not be in vain , as they will lead to valuable advances for future missions.', '["hardly","never","scarcely","barely"]', 1, 'Đáp án \'never\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_120, '[9] But even if it never leaves Earth, the efforts to achieve these ambitious goals will not be in _____ , as they will lead to valuable advances for future missions.', '["waste","vain","loss","pointless"]', 1, 'Đáp án \'vain\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Stradivarius', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nMusicians agree there’s simply [1] like a Stradivarius violin. The renowned Italian craftsman made beautiful instruments which, almost [2] fail, fetch very high prices at auctions today. Around six hundred of his violins survive and are, [3] sharp contrast to those of Niccolo Amati, relatively common, much to the surprise of [4]  who is not an expert in this field. This is to some [5] due to the fact that Stradivarius continued working well into [6] nineties. Whereas the value of an Amati violin resides mainly in its rarity, the reasons why a Stradivarius is highly sought after are different. \n\nSo what makes a Stradivarius special?  It wasn’t the materials he used as they were, by [7] large, the same as those available to contemporaries. It is more to [8] with the quality of the sound it produces. By all accounts, Stradivarius had an ideal sound in mind, and trying to achieve it made him experiment with the internal design. During his ‘golden period’ it seemed that he [9] do no wrong – every adjustment  consistently met with success.', 'C1', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_121, '[1] Musicians agree there’s simply _____ like a Stradivarius violin.', '["nothing","something","anything","everything"]', 0, 'Đáp án \'nothing\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
