INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_121, '[3] Around six hundred of his violins survive and are, _____ sharp contrast to those of Niccolo Amati, relatively common, much to the surprise of anyone who is not an expert in this field.', '["on","in","at","to"]', 1, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_121, '[4] Around six hundred of his violins survive and are, in sharp contrast to those of Niccolo Amati, relatively common, much to the surprise of _____ who is not an expert in this field.', '["everyone","someone","anyone","no one"]', 2, 'Đáp án \'anyone\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_121, '[5] This is to some _____ due to the fact that Stradivarius continued working well into his nineties.', '["in","measure","limit","extent"]', 3, 'Đáp án \'extent\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_121, '[6] This is to some extent due to the fact that Stradivarius continued working well into _____ nineties.', '["my","his","your","her"]', 1, 'Đại từ \'his\' giữ đúng vai trò ngữ pháp (tân ngữ/sở hữu/phản thân) trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_121, '[7] It wasn’t the materials he used as they were, by _____ large, the same as those available to contemporaries.', '["or","but","and","so"]', 2, 'Đáp án \'and\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
