INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_122, '[2] Floating coffee beans, dancing water droplets – you’d be forgiven for thinking you were seeing things on finding _____ faced with these phenomena.', '["himself","myself","yourself","herself"]', 2, 'Đáp án \'yourself\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
