INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_123, '[3] But thanks to recent technological developments, we may now be _____ the verge of being able to search for life beyond our solar system.', '["in","on","at","to"]', 1, 'Sử dụng giới từ \'on\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_123, '[4] However, given the vast distances between the Earth and even the nearest stars, the discovery of alien life is unlikely to lead to very _____ of a dialogue since there would be a huge time delay between each message.', '["much","many","more","most"]', 0, '\'much\' là lượng từ phù hợp với sắc thái định lượng hoặc cấu trúc so sánh trong câu.', NOW());
