INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_125, '[2] _____ companies hand out smartphones to employees, there is an implicit agreement that those staff are on call at all times.', '["For","Since","When","During"]', 2, 'Đại từ quan hệ \'When\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_125, '[3] When companies hand out smartphones to employees, there is an implicit agreement that those staff are _____ call at all times.', '["in","on","at","to"]', 1, 'Sử dụng giới từ \'on\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
