INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_126, '[7] Perhaps this explains why more and more Japanese companies are encouraging workers to sleep _____ the job.', '["in","on","at","to"]', 1, 'Sử dụng giới từ \'on\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
