INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Taking a break', 'Read the following text and choose the correct answer for each gap [1] - [9]:\n\nIn the [1] of research which clearly demonstrates that sleep helps consolidate memory, it would seem likely that taking a break from studying should, [2] and large, have a similar effect. If you have just tried to memorise a set of facts – and this could be [3] from a list of vocabulary to historical dates – then taking a break should help you to retain this information. \n\nA change of focus can also help consolidate memory, but only as [4] as it activates different parts of the brain from [5] that were previously being used. So if you have just done some hard mental work, going off to practise your tennis should [6] the trick. [7] said that, a little lie-down might seem more tempting, and may be even more productive. When it [8] to learning, we still don’t know the relative benefits of physical exercise as opposed to having a nap. Unfortunately, today’s digital world encourages us to work [9] the clock and it is therefore no wonder people are often unwilling to take a break.', 'C1', 540, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_127, '[1] In the _____ of research which clearly demonstrates that sleep helps consolidate memory, it would seem likely that taking a break from studying should, by and large, have a similar effect.', '["person","body","one","head"]', 1, 'Đáp án \'body\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_127, '[2] In the body of research which clearly demonstrates that sleep helps consolidate memory, it would seem likely that taking a break from studying should, _____ and large, have a similar effect.', '["by","in","on","at"]', 0, 'Sử dụng giới từ \'by\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
