INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_128, '[4] And it’s not just mammals that are _____ risk; even fish might be affected by discordant sounds they are simply not used to.', '["on","in","at","to"]', 2, 'Sử dụng giới từ \'at\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
