INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_128, '[7] The problem is determining what, if _____ , we can do about this.', '["nothing","something","everything","anything"]', 3, 'Đáp án \'anything\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_128, '[8] It is _____ from easy to establish which sounds underwater creatures can hear, and even, in some cases , whether they can hear at all.', '["distant","near","away","far"]', 3, 'Đáp án \'far\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
