INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('How to boost your memory', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nA cup or [1] of coffee could boost the brain’s ability to store long-term memories, or [2] researchers in the US claim. They found that people who had been given a shot of caffeine after looking at a series of pictures were better [3] to distinguish the pictures from similar images in later tests. In the experiment, 44 volunteers who had been deprived [4] coffee for at least 24 hours were shown a rapid sequence of pictures. [5] the end of the task, each volunteer was randomly assigned a caffeine pill [6] a placebo. The experiment was repeated, and the volunteers were asked [7] the pictures were the same as, similar to or different from [8] seen previously. The researcher who led the study said both groups scored equally, [9] when it came to spotting similar images. Here the caffeine group scored around 10% higher. He admits it is unclear how caffeine might help in the storage of memories, [10] is sufficiently convinced of its benefits to [11] on drinking coffee himself.', 'C1', 660, 'PUBLISHED', NOW(), NOW());
