INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_130, '[2] A cup or two of coffee could boost the brain’s ability to store long-term memories, or _____ researchers in the US claim.', '["so","because","since","as"]', 0, 'Sử dụng liên từ \'so\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
