INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_130, '[4] In the experiment, 44 volunteers who had been deprived _____ coffee for at least 24 hours were shown a rapid sequence of pictures.', '["on","in","of","at"]', 2, 'Sử dụng giới từ \'of\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
