INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_130, '[6] At the end of the task, each volunteer was randomly assigned a caffeine pill _____ a placebo.', '["or","and","but","so"]', 0, 'Đáp án \'or\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_130, '[7] The experiment was repeated, and the volunteers were asked _____ the pictures were the same as, similar to or different from those seen previously.', '["provided","unless","whether","providing"]', 2, 'Sử dụng liên từ \'whether\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_130, '[8] The experiment was repeated, and the volunteers were asked whether the pictures were the same as, similar to or different from _____ seen previously.', '["this","those","that","these"]', 1, 'Đáp án \'those\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
