INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('Writing detective fiction', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nI think I knew I would be a novelist almost as [1] as I was able to read, but for a variety of reasons, the chief one [2] the need to find a safe career, I was a late starter. [3] I did begin my first novel, I decided to try detective fiction, since it was my foremost recreational reading. [4] the time I didn’t foresee a writing future for [5] as a crime novelist, and [6], as I continued with the genre, I became increasingly intrigued by [7] possibilities.\n\nThe technical problems of a detective story are fascinating; firstly, how to balance setting, characterisation and plot so that they contribute to the whole. Then there is the creation of the detective, [8] amateur or professional, who must remain a credible human being [9] representing an agent of human justice. Perhaps the greatest problem of [10] lies in the exploration of the complexities of the murderer’s mind [11] revealing his or her identity until the final chapter.', 'C1', 660, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_131, '[1] I think I knew I would be a novelist almost as _____ as I was able to read, but for a variety of reasons, the chief one being the need to find a safe career, I was a late starter.', '["early","soon","fast","quickly"]', 1, 'Đáp án \'soon\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_131, '[2] I think I knew I would be a novelist almost as soon as I was able to read, but for a variety of reasons, the chief one _____ the need to find a safe career, I was a late starter.', '["are","am","is","being"]', 3, 'Đáp án \'being\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_131, '[3] _____ I did begin my first novel, I decided to try detective fiction, since it was my foremost recreational reading.', '["During","Since","For","When"]', 3, 'Đại từ quan hệ \'When\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_131, '[4] _____ the time I didn’t foresee a writing future for myself as a crime novelist, and yet, as I continued with the genre, I became increasingly intrigued by its possibilities.', '["On","In","At","To"]', 2, 'Sử dụng giới từ \'At\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_131, '[5] At the time I didn’t foresee a writing future for _____ as a crime novelist, and yet, as I continued with the genre, I became increasingly intrigued by its possibilities.', '["herself","yourself","himself","myself"]', 3, 'Đại từ \'myself\' giữ đúng vai trò ngữ pháp (tân ngữ/sở hữu/phản thân) trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_131, '[6] At the time I didn’t foresee a writing future for myself as a crime novelist, and _____, as I continued with the genre, I became increasingly intrigued by its possibilities.', '["although","yet","though","even though"]', 1, 'Đáp án \'yet\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_131, '[7] At the time I didn’t foresee a writing future for myself as a crime novelist, and yet, as I continued with the genre, I became increasingly intrigued by _____ possibilities.', '["your","my","its","his"]', 2, 'Đáp án \'its\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_131, '[8] Then there is the creation of the detective, _____ amateur or professional, who must remain a credible human being while representing an agent of human justice.', '["provided","if","unless","whether"]', 3, 'Sử dụng liên từ \'whether\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_131, '[9] Then there is the creation of the detective, whether amateur or professional, who must remain a credible human being _____ representing an agent of human justice.', '["for","since","while","during"]', 2, 'Sử dụng liên từ \'while\' phù hợp với cấu trúc ngữ pháp và ý nghĩa kết nối giữa hai mệnh đề.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_131, '[10] Perhaps the greatest problem of _____ lies in the exploration of the complexities of the murderer’s mind without revealing his or her identity until the final chapter.', '["both","all","each","every"]', 1, 'Dùng từ xác định/mạo từ \'all\' phù hợp với danh từ đếm được/không đếm được theo sau.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_131, '[11] Perhaps the greatest problem of all lies in the exploration of the complexities of the murderer’s mind _____ revealing his or her identity until the final chapter.', '["on","in","without","at"]', 2, 'Đáp án \'without\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO quizzes (title, description, level, time_limit, status, created_at, updated_at) VALUES ('How intelligent are dogs?', 'Read the following text and choose the correct answer for each gap [1] - [11]:\n\nFaced with a puzzle to solve for a reward, dogs give up, apparently [1] a loss, and turn to humans for help, which is quite [2] their wild cousins, wolves. So are dogs just servile creatures [3] dependence on humans has made them less intelligent than wolves? \n\nThe answer is by no [4] straightforward. Researchers presented wolves and dogs with a box containing a snack, which could be opened with a certain [5] of persistence. Most wolves managed to open the box, but only one [6] twenty dogs succeeded. Whereas the wolves spent all of their time engaged with the task, those dogs who attempted it spent almost [7] at all. By and [8] , the dogs declined even to attempt the task, and only tried [9] encouraged by a human.\n\nSome scientists believe the domestication of dogs has conditioned them to seek direction from a human, [10] of how clever they actually are. Other experts warn that, [11] the behavioural variability among dogs, it is unwise to generalise.', 'C1', 660, 'PUBLISHED', NOW(), NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_132, '[1] Faced with a puzzle to solve for a reward, dogs give up, apparently _____ a loss, and turn to humans for help, which is quite unlike their wild cousins, wolves.', '["to","in","on","at"]', 3, 'Sử dụng giới từ \'at\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_132, '[2] Faced with a puzzle to solve for a reward, dogs give up, apparently at a loss, and turn to humans for help, which is quite _____ their wild cousins, wolves.', '["unlike","different","opposite","dislike"]', 0, 'Đáp án \'unlike\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_132, '[3] So are dogs just servile creatures _____ dependence on humans has made them less intelligent than wolves?', '["whose","who","whom","which"]', 0, 'Đại từ quan hệ \'whose\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_132, '[4] The answer is by no _____ straightforward.', '["way","means","manner","method"]', 1, 'Đáp án \'means\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_132, '[5] Researchers presented wolves and dogs with a box containing a snack, which could be opened with a certain _____ of persistence.', '["deal","number","quantity","amount"]', 3, 'Đáp án \'amount\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_132, '[6] Most wolves managed to open the box, but only one _____ twenty dogs succeeded.', '["in","on","at","to"]', 0, 'Sử dụng giới từ \'in\' là chính xác nhất theo quy tắc ngữ pháp hoặc ngữ cảnh/cụm từ đi kèm trong câu.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_132, '[7] Whereas the wolves spent all of their time engaged with the task, those dogs who attempted it spent almost _____ at all.', '["each","all","both","none"]', 3, 'Đáp án \'none\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_132, '[8] By and _____ , the dogs declined even to attempt the task, and only tried when encouraged by a human.', '["great","large","big","huge"]', 1, 'Đáp án \'large\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_132, '[9] By and large , the dogs declined even to attempt the task, and only tried _____ encouraged by a human.', '["since","when","for","during"]', 1, 'Đại từ quan hệ \'when\' được dùng để liên kết mệnh đề và thay thế cho danh từ đứng trước.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_132, '[10] Some scientists believe the domestication of dogs has conditioned them to seek direction from a human, _____ of how clever they actually are.', '["regardless","irrespective","despite","careless"]', 0, 'Đáp án \'regardless\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
INSERT INTO questions (quiz_id, content, options, correct_answer, explanation, created_at) VALUES (@quiz_id_132, '[11] Other experts warn that, _____ the behavioural variability among dogs, it is unwise to generalise.', '["given","provided","assuming","in"]', 0, 'Đáp án \'given\' là từ phù hợp nhất về mặt ngữ pháp và kết hợp từ (collocation) trong ngữ cảnh này.', NOW());
